{
  "name": "CalorieBD AI",
  "description": "A specialized AI nutrition tracker for Bangladeshi cuisine, helping users track calories and macros using image recognition and local food knowledge.",
  "requestFramePermissions": [
    "camera"
  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface NutritionInfo {
  calories: number;
  protein: number;
  carbs: number;
  fat: number;
  fiber?: number;
}

export interface Meal {
  id: string;
  name: string;
  timestamp: number;
  image?: string;
  nutrition: NutritionInfo;
  ingredients: string[];
  portionSize: string;
}

export interface UserProfile {
  name: string;
  weight: number;
  height: number;
  age: number;
  gender: 'male' | 'female' | 'other';
  activityLevel: 'sedentary' | 'light' | 'moderate' | 'active';
  dailyGoal: number;
}

export interface FoodAnalysisResult {
  foodName: string;
  confidence: number;
  estimatedNutrition: NutritionInfo;
  ingredientsFound: string[];
  suggestedPortion: string;
}

import { GoogleGenAI, Type } from "@google/genai";
import { FoodAnalysisResult } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });

export const analyzeMealImage = async (base64Image: string, userContext?: string): Promise<FoodAnalysisResult> => {
  const model = "gemini-3-flash-preview";

  const systemInstruction = `
    You are a professional Nutritionist specializing in Bangladeshi Cuisine (Bengali Food).
    Your task is to analyze an image of a meal and provide nutritional information.
    Recognize specific Bangladeshi dishes such as: Biryani (Kacchi, Tehari), Bhuna Khichuri, Panta Ilish, 
    various Bhortas (Alu, Begun, Shutki), Curries (Fish, Mutton, Beef), Pithas, and snacks like Chotpoti or Fuchka.

    Be realistic about oil and ghee content common in Bengali cooking.
    Provide the response in structured JSON.
  `;

  const prompt = `
    Analyze this meal image. ${userContext ? `User says: ${userContext}` : ""}
    Estimate the portion size and nutritional values (calories, protein, carbs, fat).
    Focus on accuracy for Bangladeshi portion standards.
  `;

  const response = await ai.models.generateContent({
    model,
    contents: {
      parts: [
        { inlineData: { mimeType: "image/jpeg", data: base64Image } },
        { text: prompt }
      ]
    },
    config: {
      systemInstruction,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          foodName: { type: Type.STRING },
          confidence: { type: Type.NUMBER },
          estimatedNutrition: {
            type: Type.OBJECT,
            properties: {
              calories: { type: Type.NUMBER },
              protein: { type: Type.NUMBER },
              carbs: { type: Type.NUMBER },
              fat: { type: Type.NUMBER },
              fiber: { type: Type.NUMBER }
            },
            required: ["calories", "protein", "carbs", "fat"]
          },
          ingredientsFound: {
            type: Type.ARRAY,
            items: { type: Type.STRING }
          },
          suggestedPortion: { type: Type.STRING }
        },
        required: ["foodName", "estimatedNutrition", "ingredientsFound", "suggestedPortion"]
      }
    }
  });

  try {
    return JSON.parse(response.text || "{}") as FoodAnalysisResult;
  } catch (error) {
    console.error("Failed to parse Gemini response:", error);
    throw new Error("Could not analyze the meal image.");
  }
};

import React, { useState, useEffect, useCallback } from 'react';
import { Meal, UserProfile, NutritionInfo } from './types';
import { analyzeMealImage } from './services/geminiService';
import Dashboard from './components/Dashboard';
import MealLogger from './components/MealLogger';
import ProfileSetup from './components/ProfileSetup';
import Header from './components/Header';
import Footer from './components/Footer';

const App: React.FC = () => {
  const [view, setView] = useState<'dashboard' | 'logger' | 'profile'>('dashboard');
  const [meals, setMeals] = useState<Meal[]>([]);
  const [profile, setProfile] = useState<UserProfile | null>(null);
  const [isLoading, setIsLoading] = useState(false);

  // Load data from localStorage on mount
  useEffect(() => {
    const savedMeals = localStorage.getItem('caloriebd_meals');
    const savedProfile = localStorage.getItem('caloriebd_profile');

    if (savedMeals) setMeals(JSON.parse(savedMeals));
    if (savedProfile) {
      setProfile(JSON.parse(savedProfile));
    } else {
      setView('profile');
    }
  }, []);

  // Save data whenever it changes
  useEffect(() => {
    localStorage.setItem('caloriebd_meals', JSON.stringify(meals));
  }, [meals]);

  useEffect(() => {
    if (profile) localStorage.setItem('caloriebd_profile', JSON.stringify(profile));
  }, [profile]);

  const handleAddMeal = (meal: Meal) => {
    setMeals(prev => [meal, ...prev]);
    setView('dashboard');
  };

  const handleDeleteMeal = (id: string) => {
    setMeals(prev => prev.filter(m => m.id !== id));
  };

  const handleUpdateProfile = (newProfile: UserProfile) => {
    setProfile(newProfile);
    setView('dashboard');
  };

  return (
    <div className="min-h-screen flex flex-col max-w-md mx-auto bg-white shadow-xl relative overflow-hidden">
      <Header setView={setView} currentView={view} />

      <main className="flex-1 overflow-y-auto pb-24">
        {view === 'dashboard' && profile && (
          <Dashboard 
            meals={meals} 
            profile={profile} 
            onDeleteMeal={handleDeleteMeal}
            onAddClick={() => setView('logger')}
          />
        )}

        {view === 'logger' && (
          <MealLogger 
            onSave={handleAddMeal} 
            onCancel={() => setView('dashboard')}
            isLoading={isLoading}
            setIsLoading={setIsLoading}
          />
        )}

        {view === 'profile' && (
          <ProfileSetup 
            profile={profile} 
            onSave={handleUpdateProfile} 
            onCancel={profile ? () => setView('dashboard') : undefined}
          />
        )}
      </main>

      <Footer setView={setView} currentView={view} />
    </div>
  );
};

export default App;

import React from 'react';

interface HeaderProps {
  setView: (view: 'dashboard' | 'logger' | 'profile') => void;
  currentView: string;
}

const Header: React.FC<HeaderProps> = ({ setView, currentView }) => {
