    <header className="sticky top-0 z-50 bg-white/80 backdrop-blur-md border-b border-gray-100 p-4 flex items-center justify-between">
      <div 
        className="flex items-center gap-2 cursor-pointer" 
        onClick={() => setView('dashboard')}
      >
        <div className="bg-emerald-600 p-2 rounded-xl text-white shadow-lg shadow-emerald-200">
          <i className="fas fa-fire-flame-curved text-xl"></i>
        </div>
        <div>
          <h1 className="font-bold text-lg leading-tight">Calorie<span className="text-emerald-600">BD</span></h1>
          <p className="text-[10px] text-gray-400 font-medium tracking-widest uppercase">AI Nutritionist</p>
        </div>
      </div>

      <button 
        onClick={() => setView('profile')}
        className={`w-10 h-10 rounded-full flex items-center justify-center transition-all ${
