export default Header;

import React from 'react';
import { Meal, UserProfile, NutritionInfo } from '../types';
import { PieChart, Pie, Cell, ResponsiveContainer } from 'recharts';

interface DashboardProps {
  meals: Meal[];
  profile: UserProfile;
  onDeleteMeal: (id: string) => void;
  onAddClick: () => void;
}

const Dashboard: React.FC<DashboardProps> = ({ meals, profile, onDeleteMeal, onAddClick }) => {
  const today = new Date().setHours(0, 0, 0, 0);
  const todayMeals = meals.filter(m => m.timestamp >= today);

  const totals = todayMeals.reduce((acc, meal) => ({
    calories: acc.calories + meal.nutrition.calories,
    protein: acc.protein + meal.nutrition.protein,
    carbs: acc.carbs + meal.nutrition.carbs,
    fat: acc.fat + meal.nutrition.fat,
  }), { calories: 0, protein: 0, carbs: 0, fat: 0 });

  const calorieProgress = Math.min((totals.calories / profile.dailyGoal) * 100, 100);
  const remaining = Math.max(profile.dailyGoal - totals.calories, 0);

  const chartData = [
    { name: 'Consumed', value: totals.calories },
    { name: 'Remaining', value: remaining }
  ];

  const COLORS = ['#059669', '#E5E7EB'];

  return (
    <div className="p-4 space-y-6">
      {/* Daily Progress Card */}
      <section className="bg-gradient-to-br from-emerald-600 to-emerald-700 rounded-3xl p-6 text-white shadow-xl shadow-emerald-100">
        <div className="flex justify-between items-start mb-4">
          <div>
            <h2 className="text-emerald-100 text-sm font-medium">Daily Calories</h2>
            <div className="text-4xl font-bold mt-1">
              {totals.calories.toLocaleString()}
              <span className="text-lg font-normal text-emerald-100 opacity-80"> / {profile.dailyGoal}</span>
            </div>
          </div>
          <div className="h-20 w-20">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={chartData}
                  cx="50%"
                  cy="50%"
                  innerRadius={25}
                  outerRadius={35}
                  paddingAngle={5}
                  dataKey="value"
                  stroke="none"
                >
                  {chartData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={COLORS[index]} />
                  ))}
                </Pie>
              </PieChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="grid grid-cols-3 gap-4 border-t border-emerald-500/30 pt-4 mt-2">
          <div className="text-center">
            <div className="text-xs text-emerald-100/70 font-medium">Protein</div>
            <div className="font-bold text-lg">{Math.round(totals.protein)}g</div>
          </div>
          <div className="text-center">
            <div className="text-xs text-emerald-100/70 font-medium">Carbs</div>
            <div className="font-bold text-lg">{Math.round(totals.carbs)}g</div>
          </div>
          <div className="text-center">
            <div className="text-xs text-emerald-100/70 font-medium">Fat</div>
            <div className="font-bold text-lg">{Math.round(totals.fat)}g</div>
          </div>
        </div>
      </section>

      {/* Quick Actions */}
      <section>
        <button 
          onClick={onAddClick}
          className="w-full bg-white border-2 border-dashed border-emerald-500 rounded-2xl p-4 flex items-center justify-center gap-3 text-emerald-600 font-semibold hover:bg-emerald-50 transition-colors"
        >
          <div className="bg-emerald-100 p-2 rounded-full">
            <i className="fas fa-camera text-xl"></i>
          </div>
          Log Bangladeshi Meal
        </button>
      </section>

      {/* Meal History */}
      <section className="space-y-4">
        <h3 className="font-bold text-gray-800 px-1">Today's Logs</h3>
        {todayMeals.length === 0 ? (
          <div className="text-center py-12 bg-gray-50 rounded-3xl border-2 border-dotted border-gray-200">
            <div className="bg-white w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4 text-gray-300">
              <i className="fas fa-utensils text-2xl"></i>
            </div>
            <p className="text-gray-400 font-medium">No meals logged today</p>
            <p className="text-xs text-gray-400 mt-1 px-8">Track your Biryani, Tehari or Bhorta meals easily!</p>
          </div>
        ) : (
          <div className="space-y-3">
            {todayMeals.map((meal) => (
              <div key={meal.id} className="bg-white p-3 rounded-2xl flex items-center gap-4 border border-gray-100 shadow-sm group">
                {meal.image ? (
                  <img src={meal.image} alt={meal.name} className="w-16 h-16 rounded-xl object-cover" />
                ) : (
                  <div className="w-16 h-16 rounded-xl bg-gray-100 flex items-center justify-center text-gray-400">
                    <i className="fas fa-bowl-rice"></i>
                  </div>
                )}
                <div className="flex-1">
                  <h4 className="font-bold text-gray-800 leading-tight">{meal.name}</h4>
                  <p className="text-xs text-gray-500 mt-0.5">{new Date(meal.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })} • {meal.portionSize}</p>
                  <div className="flex gap-3 mt-1.5">
                    <span className="text-[10px] font-bold px-1.5 py-0.5 rounded bg-emerald-50 text-emerald-700 uppercase">P: {Math.round(meal.nutrition.protein)}g</span>
                    <span className="text-[10px] font-bold px-1.5 py-0.5 rounded bg-amber-50 text-amber-700 uppercase">C: {Math.round(meal.nutrition.carbs)}g</span>
                    <span className="text-[10px] font-bold px-1.5 py-0.5 rounded bg-rose-50 text-rose-700 uppercase">F: {Math.round(meal.nutrition.fat)}g</span>
                  </div>
                </div>
                <div className="text-right">
                  <div className="font-bold text-gray-900">{meal.nutrition.calories}</div>
                  <div className="text-[10px] text-gray-400 uppercase font-bold">kcal</div>
                  <button 
                    onClick={() => onDeleteMeal(meal.id)}
                    className="mt-2 text-gray-300 hover:text-rose-500 transition-colors opacity-0 group-hover:opacity-100"
                  >
                    <i className="fas fa-trash-alt text-xs"></i>
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}
      </section>
    </div>
  );
};

export default Dashboard;

import React, { useState, useRef, useCallback } from 'react';
import { analyzeMealImage } from '../services/geminiService';
import { Meal, FoodAnalysisResult } from '../types';

interface MealLoggerProps {
  onSave: (meal: Meal) => void;
  onCancel: () => void;
  isLoading: boolean;
  setIsLoading: (loading: boolean) => void;
}

const MealLogger: React.FC<MealLoggerProps> = ({ onSave, onCancel, isLoading, setIsLoading }) => {
  const [capturedImage, setCapturedImage] = useState<string | null>(null);
  const [analysis, setAnalysis] = useState<FoodAnalysisResult | null>(null);
  const [userContext, setUserContext] = useState('');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64 = reader.result as string;
        setCapturedImage(base64);
        handleAnalyze(base64);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleAnalyze = async (image: string) => {
    setIsLoading(true);
    try {
      const base64Data = image.split(',')[1];
      const result = await analyzeMealImage(base64Data, userContext);
      setAnalysis(result);
    } catch (error) {
      console.error(error);
      alert("Analysis failed. Please try again.");
    } finally {
      setIsLoading(false);
    }
  };

  const handleConfirmSave = () => {
    if (analysis) {
      const newMeal: Meal = {
        id: Date.now().toString(),
        name: analysis.foodName,
        timestamp: Date.now(),
        image: capturedImage || undefined,
        nutrition: analysis.estimatedNutrition,
        ingredients: analysis.ingredientsFound,
        portionSize: analysis.suggestedPortion
      };
      onSave(newMeal);
    }
  };

  return (
    <div className="p-4 flex flex-col min-h-full">
      <div className="flex items-center justify-between mb-6">
        <button onClick={onCancel} className="text-gray-500 hover:text-gray-800">
          <i className="fas fa-chevron-left mr-1"></i> Back
        </button>
        <h2 className="font-bold text-xl">Log Your Meal</h2>
        <div className="w-8"></div>
      </div>

      {!capturedImage ? (
        <div className="flex-1 flex flex-col items-center justify-center space-y-8">
          <div className="w-full max-w-[280px] aspect-square bg-gray-50 border-2 border-dashed border-gray-200 rounded-3xl flex flex-col items-center justify-center text-center p-6 space-y-4">
            <div className="w-20 h-20 bg-emerald-100 text-emerald-600 rounded-full flex items-center justify-center text-3xl">
              <i className="fas fa-camera"></i>
            </div>
            <div>
              <p className="font-bold text-gray-700">Take a Photo</p>
              <p className="text-sm text-gray-400 mt-1 px-4">Our AI specialized in Bangladeshi food will identify it</p>
            </div>
          </div>

          <div className="w-full space-y-3">
            <button 
              onClick={() => fileInputRef.current?.click()}
              className="w-full bg-emerald-600 text-white font-bold py-4 rounded-2xl shadow-lg shadow-emerald-100 flex items-center justify-center gap-2"
            >
              <i className="fas fa-camera"></i>
              Open Camera / Gallery
            </button>
            <input 
              type="file" 
              accept="image/*" 
              className="hidden" 
              ref={fileInputRef} 
              onChange={handleFileChange}
            />
          </div>
        </div>
      ) : (
        <div className="space-y-6">
          <div className="relative group overflow-hidden rounded-3xl shadow-lg border border-gray-100">
            <img src={capturedImage} alt="Captured meal" className="w-full h-64 object-cover" />
            {isLoading && (
              <div className="absolute inset-0 bg-black/40 backdrop-blur-sm flex flex-col items-center justify-center text-white p-6 text-center">
                <div className="w-12 h-12 border-4 border-emerald-500 border-t-transparent rounded-full animate-spin mb-4"></div>
                <p className="font-bold text-lg">Analyzing Your Meal...</p>
                <p className="text-sm opacity-80 mt-1">Identifying Biryani, Bhorta, or Fish Curry ingredients</p>
              </div>
            )}
          </div>

          {!isLoading && analysis && (
            <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-500">
              <div className="bg-emerald-50 rounded-2xl p-4 border border-emerald-100">
                <div className="flex justify-between items-start mb-2">
                  <h3 className="text-xl font-bold text-emerald-900">{analysis.foodName}</h3>
                  <div className="bg-emerald-200/50 px-2 py-0.5 rounded text-[10px] font-bold text-emerald-700">
                    {Math.round(analysis.confidence * 100)}% CONFIDENT
                  </div>
                </div>
                <p className="text-sm text-emerald-700/80 mb-4">{analysis.suggestedPortion}</p>

                <div className="grid grid-cols-4 gap-2">
                  <div className="bg-white p-2 rounded-xl text-center shadow-sm">
                    <div className="text-xs text-gray-400 uppercase font-bold">Kcal</div>
                    <div className="font-bold text-emerald-600 text-lg">{analysis.estimatedNutrition.calories}</div>
                  </div>
                  <div className="bg-white p-2 rounded-xl text-center shadow-sm">
                    <div className="text-xs text-gray-400 uppercase font-bold">Prot</div>
                    <div className="font-bold text-blue-600 text-lg">{Math.round(analysis.estimatedNutrition.protein)}g</div>
                  </div>
                  <div className="bg-white p-2 rounded-xl text-center shadow-sm">
                    <div className="text-xs text-gray-400 uppercase font-bold">Carb</div>
                    <div className="font-bold text-amber-600 text-lg">{Math.round(analysis.estimatedNutrition.carbs)}g</div>
                  </div>
                  <div className="bg-white p-2 rounded-xl text-center shadow-sm">
                    <div className="text-xs text-gray-400 uppercase font-bold">Fat</div>
                    <div className="font-bold text-rose-600 text-lg">{Math.round(analysis.estimatedNutrition.fat)}g</div>
                  </div>
                </div>
              </div>

              <div className="space-y-2 px-1">
                <h4 className="font-bold text-gray-700 text-sm">Detected Ingredients</h4>
                <div className="flex flex-wrap gap-2">
                  {analysis.ingredientsFound.map((ing, i) => (
                    <span key={i} className="text-xs bg-gray-100 text-gray-600 px-3 py-1.5 rounded-full font-medium border border-gray-200">
                      {ing}
                    </span>
                  ))}
                </div>
              </div>

              <div className="flex gap-3 sticky bottom-4 pt-4 bg-white">
                <button 
                  onClick={() => setCapturedImage(null)}
                  className="flex-1 bg-gray-100 text-gray-600 font-bold py-4 rounded-2xl border border-gray-200"
                >
                  Retake
                </button>
                <button 
                  onClick={handleConfirmSave}
                  className="flex-[2] bg-emerald-600 text-white font-bold py-4 rounded-2xl shadow-lg shadow-emerald-100"
                >
                  Add to Daily Log
                </button>
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export default MealLogger;

import React, { useState } from 'react';
import { UserProfile } from '../types';

interface ProfileSetupProps {
  profile: UserProfile | null;
  onSave: (profile: UserProfile) => void;
  onCancel?: () => void;
}

const ProfileSetup: React.FC<ProfileSetupProps> = ({ profile, onSave, onCancel }) => {
  const [formData, setFormData] = useState<UserProfile>(profile || {
    name: '',
    weight: 70,
    height: 170,
    age: 25,
    gender: 'male',
    activityLevel: 'moderate',
    dailyGoal: 2000
  });

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: name === 'gender' || name === 'activityLevel' || name === 'name' ? value : Number(value)
    }));
  };

  const calculateSuggestedCalories = () => {
    // Basic Mifflin-St Jeor Equation
    let bmr = 0;
    if (formData.gender === 'male') {
      bmr = 10 * formData.weight + 6.25 * formData.height - 5 * formData.age + 5;
    } else {
      bmr = 10 * formData.weight + 6.25 * formData.height - 5 * formData.age - 161;
    }

    const activityMultipliers = {
      sedentary: 1.2,
      light: 1.375,
      moderate: 1.55,
      active: 1.725
    };

    const tdee = bmr * activityMultipliers[formData.activityLevel];
    setFormData(prev => ({ ...prev, dailyGoal: Math.round(tdee) }));
  };

  return (
    <div className="p-6">
      <div className="mb-8">
        <h2 className="text-2xl font-bold text-gray-900">Health Profile</h2>
        <p className="text-gray-500 text-sm mt-1">Set your goals for personalized tracking</p>
      </div>

      <div className="space-y-6">
        <div className="space-y-4">
          <div>
            <label className="block text-xs font-bold text-gray-400 uppercase mb-1.5 ml-1">Your Name</label>
            <input 
              type="text" 
              name="name" 
              value={formData.name} 
              onChange={handleChange}
              placeholder="e.g. Rahul"
              className="w-full bg-gray-50 border border-gray-200 rounded-2xl px-4 py-3 focus:ring-2 focus:ring-emerald-500 focus:outline-none"
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-bold text-gray-400 uppercase mb-1.5 ml-1">Weight (kg)</label>
              <input 
                type="number" 
                name="weight" 
                value={formData.weight} 
                onChange={handleChange}
                className="w-full bg-gray-50 border border-gray-200 rounded-2xl px-4 py-3 focus:ring-2 focus:ring-emerald-500 focus:outline-none"
              />
            </div>
            <div>
              <label className="block text-xs font-bold text-gray-400 uppercase mb-1.5 ml-1">Height (cm)</label>
              <input 
                type="number" 
                name="height" 
                value={formData.height} 
                onChange={handleChange}
                className="w-full bg-gray-50 border border-gray-200 rounded-2xl px-4 py-3 focus:ring-2 focus:ring-emerald-500 focus:outline-none"
              />
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-bold text-gray-400 uppercase mb-1.5 ml-1">Age</label>
              <input 
                type="number" 
                name="age" 
                value={formData.age} 
