import React, { useState, useRef } from 'react';
import { GroceryItem, Recipe } from '../types';
import { analyzeGroceries, generateRecipeFromGroceries } from '../services/geminiService';

interface PantryViewProps {
  items: GroceryItem[];
  setItems: (items: GroceryItem[]) => void;
}

const PantryView: React.FC<PantryViewProps> = ({ items, setItems }) => {
  const [isScanning, setIsScanning] = useState(false);
  const [isGenerating, setIsGenerating] = useState(false);
  const [recipe, setRecipe] = useState<Recipe | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleScan = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsScanning(true);
    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64 = (reader.result as string).split(',')[1];
      try {
        const detected = await analyzeGroceries(base64);
        setItems([...detected, ...items]);
      } catch (err) {
        alert("Failed to scan items");
      } finally {
        setIsScanning(false);
      }
    };
    reader.readAsDataURL(file);
  };

  const handleGetRecipe = async () => {
    if (items.length === 0) return;
    setIsGenerating(true);
    try {
      const result = await generateRecipeFromGroceries(items.map(i => i.name));
      setRecipe(result);
    } catch (err) {
      alert("Failed to generate recipe");
    } finally {
      setIsGenerating(false);
    }
  };

  return (
    <div className="p-4 space-y-6">
      <div className="flex justify-between items-center">
        <h2 className="text-2xl font-bold text-gray-800">My Pantry</h2>
        <button 
          onClick={() => fileInputRef.current?.click()}
          className="bg-emerald-100 text-emerald-700 px-4 py-2 rounded-xl text-sm font-bold flex items-center gap-2"
          disabled={isScanning}
        >
          <i className={`fas ${isScanning ? 'fa-spinner fa-spin' : 'fa-plus'}`}></i>
          {isScanning ? 'Scanning...' : 'Scan Items'}
        </button>
        <input type="file" className="hidden" ref={fileInputRef} onChange={handleScan} accept="image/*" />
      </div>

      <div className="flex flex-wrap gap-2">
        {items.length === 0 && !isScanning && (
          <div className="text-center w-full py-12 text-gray-400">
            <i className="fas fa-shopping-basket text-4xl mb-4 opacity-20"></i>
            <p>Your pantry is empty.<br/>Scan some groceries to start!</p>
          </div>
        )}
        {items.map(item => (
          <div key={item.id} className="bg-white border border-gray-100 px-3 py-2 rounded-xl shadow-sm flex items-center gap-2 group animate-in fade-in zoom-in-95">
            <span className="font-medium text-gray-700">{item.name}</span>
            <button 
              onClick={() => setItems(items.filter(i => i.id !== item.id))}
              className="text-gray-300 hover:text-rose-500 transition-colors"
            >
              <i className="fas fa-times-circle text-xs"></i>
            </button>
          </div>
        ))}
      </div>

      {items.length > 0 && (
        <button 
          onClick={handleGetRecipe}
          disabled={isGenerating}
          className="w-full bg-emerald-600 text-white font-bold py-4 rounded-2xl shadow-lg flex items-center justify-center gap-3 transition-all hover:bg-emerald-700 disabled:bg-gray-300"
        >
          {isGenerating ? (
            <i className="fas fa-mortar-pestle fa-spin"></i>
          ) : (
            <i className="fas fa-hat-chef"></i>
          )}
          {isGenerating ? 'Cooking up ideas...' : 'Generate AI Recipe'}
        </button>
      )}

      {recipe && (
        <div className="bg-white rounded-3xl border border-gray-100 shadow-xl p-6 space-y-4 animate-in slide-in-from-bottom-8">
          <div className="flex justify-between items-start">
            <h3 className="text-2xl font-bold text-gray-900 leading-tight">{recipe.title}</h3>
            <button onClick={() => setRecipe(null)} className="text-gray-400"><i className="fas fa-times"></i></button>
          </div>

          <div className="flex gap-4 text-xs font-bold text-emerald-600 uppercase tracking-wider">
            <span><i className="fas fa-clock mr-1"></i> {recipe.prepTime}</span>
            <span><i className="fas fa-user-group mr-1"></i> {recipe.servings} Servings</span>
          </div>

          <div className="bg-emerald-50 p-4 rounded-2xl italic text-sm text-emerald-800">
            "{recipe.bangladeshiContext}"
          </div>

          <div className="space-y-2">
            <h4 className="font-bold text-gray-800 border-b pb-1">Ingredients</h4>
            <ul className="text-sm text-gray-600 space-y-1">
              {recipe.ingredients.map((ing, i) => (
                <li key={i} className="flex items-center gap-2">
                  <div className="w-1.5 h-1.5 rounded-full bg-emerald-400"></div>
                  {ing}
                </li>
              ))}
            </ul>
          </div>

          <div className="space-y-3">
            <h4 className="font-bold text-gray-800 border-b pb-1">Instructions</h4>
            <div className="space-y-4">
              {recipe.instructions.map((step, i) => (
                <div key={i} className="flex gap-3">
                  <span className="font-black text-emerald-200 text-2xl leading-none">{i+1}</span>
                  <p className="text-sm text-gray-600 flex-1">{step}</p>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

