import { GoogleGenAI, Type } from "@google/genai";
import { FoodAnalysisResult, GroceryItem, Recipe } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });

export const analyzeMealImage = async (base64Image: string, userContext?: string): Promise<FoodAnalysisResult> => {
  const model = "gemini-3-flash-preview";
  const systemInstruction = `
    You are a professional Nutritionist with global expertise.
    Analyze the meal image and provide nutritional info. Expert in Global and Bangladeshi cuisines.
    Provide the response in structured JSON.
  `;
  const response = await ai.models.generateContent({
    model,
    contents: {
      parts: [
        { inlineData: { mimeType: "image/jpeg", data: base64Image } },
        { text: `Analyze this meal. ${userContext || ""}` }
      ]
    },
    config: {
      systemInstruction,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          foodName: { type: Type.STRING },
          confidence: { type: Type.NUMBER },
          estimatedNutrition: {
            type: Type.OBJECT,
            properties: {
              calories: { type: Type.NUMBER },
              protein: { type: Type.NUMBER },
              carbs: { type: Type.NUMBER },
              fat: { type: Type.NUMBER }
            },
            required: ["calories", "protein", "carbs", "fat"]
          },
          ingredientsFound: { type: Type.ARRAY, items: { type: Type.STRING } },
          suggestedPortion: { type: Type.STRING }
        },
        required: ["foodName", "estimatedNutrition", "ingredientsFound", "suggestedPortion"]
      }
    }
  });
  return JSON.parse(response.text || "{}");
};

export const analyzeGroceries = async (base64Image: string): Promise<GroceryItem[]> => {
  const model = "gemini-3-flash-preview";
  const systemInstruction = "Identify all raw grocery items. Recognize items from global and local markets.";
  const response = await ai.models.generateContent({
    model,
    contents: {
      parts: [
        { inlineData: { mimeType: "image/jpeg", data: base64Image } },
        { text: "List items found." }
      ]
    },
    config: {
      systemInstruction,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            name: { type: Type.STRING },
            category: { type: Type.STRING }
          },
          required: ["name", "category"]
        }
      }
    }
  });
  const results = JSON.parse(response.text || "[]");
  return results.map((item: any) => ({ ...item, id: Math.random().toString(36).substr(2, 9) }));
};

export const generateRecipeFromGroceries = async (pantryItems: string[]): Promise<Recipe> => {
  const model = "gemini-3-flash-preview";
  const systemInstruction = `
    You are a Master Chef. Create a Halal-friendly recipe (No Pork, No Alcohol).
    You will be given a list of ingredients currently in the user's pantry.
    Suggest a dish that primarily uses these, but you may include essential missing items.

    For missing items:
    1. List them in 'missingIngredients'.
    2. Suggest a 'alternative' substitution if possible (e.g. 'Butter' if 'Ghee' is missing).

    Provide structured JSON output.
  `;

  const response = await ai.models.generateContent({
    model,
    contents: `The user has: ${pantryItems.join(", ")}. Suggest the best possible recipe.`,
    config: {
      systemInstruction,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          title: { type: Type.STRING },
          description: { type: Type.STRING },
          prepTime: { type: Type.STRING },
          servings: { type: Type.NUMBER },
          ingredients: { type: Type.ARRAY, items: { type: Type.STRING } },
          instructions: { type: Type.ARRAY, items: { type: Type.STRING } },
          bangladeshiContext: { type: Type.STRING },
          missingIngredients: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                name: { type: Type.STRING },
                alternative: { type: Type.STRING }
              },
              required: ["name"]
            }
          }
        },
        required: ["title", "description", "prepTime", "ingredients", "instructions", "missingIngredients"]
      }
    }
  });

  return JSON.parse(response.text || "{}");
};

import React, { useState, useRef } from 'react';
import { GroceryItem, Recipe } from '../types';
import { analyzeGroceries, generateRecipeFromGroceries } from '../services/geminiService';

interface PantryViewProps {
  items: GroceryItem[];
  setItems: (items: GroceryItem[]) => void;
}

const PantryView: React.FC<PantryViewProps> = ({ items, setItems }) => {
  const [isScanning, setIsScanning] = useState(false);
  const [isGenerating, setIsGenerating] = useState(false);
  const [recipe, setRecipe] = useState<Recipe | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleScan = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setIsScanning(true);
    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64 = (reader.result as string).split(',')[1];
      try {
        const detected = await analyzeGroceries(base64);
        setItems([...detected, ...items]);
      } catch (err) {
        alert("Failed to scan items");
      } finally {
        setIsScanning(false);
      }
    };
    reader.readAsDataURL(file);
  };

  const handleGetRecipe = async () => {
    if (items.length === 0) return;
    setIsGenerating(true);
    try {
      const result = await generateRecipeFromGroceries(items.map(i => i.name));
      setRecipe(result);
    } catch (err) {
      alert("Failed to generate recipe");
    } finally {
      setIsGenerating(false);
    }
  };

  const openOrderLink = (item: string, platform: 'chaldal' | 'foodpanda' | 'pathao') => {
    const query = encodeURIComponent(item);
    let url = '';
    switch(platform) {
      case 'chaldal': url = `https://chaldal.com/search/${query}`; break;
      case 'foodpanda': url = `https://www.foodpanda.com.bd/darkstore/search?q=${query}`; break;
      case 'pathao': url = `https://pathao.com/food/search?q=${query}`; break;
    }
    window.open(url, '_blank');
  };

  return (
    <div className="p-4 space-y-6">
      <div className="flex justify-between items-center">
        <h2 className="text-2xl font-bold text-gray-800">My Pantry</h2>
        <button 
          onClick={() => fileInputRef.current?.click()}
          className="bg-emerald-100 text-emerald-700 px-4 py-2 rounded-xl text-sm font-bold flex items-center gap-2"
          disabled={isScanning}
        >
          <i className={`fas ${isScanning ? 'fa-spinner fa-spin' : 'fa-plus'}`}></i>
          {isScanning ? 'Scanning...' : 'Scan Groceries'}
        </button>
        <input type="file" className="hidden" ref={fileInputRef} onChange={handleScan} accept="image/*" />
      </div>

      <div className="flex flex-wrap gap-2">
        {items.length === 0 && !isScanning && (
          <div className="text-center w-full py-12 text-gray-400">
            <i className="fas fa-basket-shopping text-4xl mb-4 opacity-20"></i>
            <p>Your pantry is empty.<br/>Scan items from your fridge!</p>
          </div>
        )}
        {items.map(item => (
          <div key={item.id} className="bg-white border border-gray-100 px-3 py-2 rounded-xl shadow-sm flex items-center gap-2 group animate-in fade-in zoom-in-95">
            <span className="font-medium text-gray-700">{item.name}</span>
            <button onClick={() => setItems(items.filter(i => i.id !== item.id))} className="text-gray-300 hover:text-rose-500 transition-colors">
              <i className="fas fa-times-circle text-xs"></i>
            </button>
          </div>
        ))}
      </div>

      {items.length > 0 && (
        <button 
          onClick={handleGetRecipe}
          disabled={isGenerating}
          className="w-full bg-emerald-600 text-white font-bold py-4 rounded-2xl shadow-lg flex items-center justify-center gap-3 transition-all hover:bg-emerald-700 disabled:bg-gray-300"
        >
          {isGenerating ? <i className="fas fa-mortar-pestle fa-spin"></i> : <i className="fas fa-hat-chef"></i>}
          {isGenerating ? 'Analyzing Pantry...' : 'Get Recipe & Order Items'}
        </button>
      )}

      {recipe && (
        <div className="bg-white rounded-3xl border border-gray-100 shadow-xl p-6 space-y-6 animate-in slide-in-from-bottom-8">
          <div className="flex justify-between items-start">
            <div>
              <span className="bg-emerald-100 text-emerald-700 text-[10px] font-black px-2 py-0.5 rounded-full uppercase tracking-widest flex items-center gap-1 mb-2 w-fit">
                <i className="fas fa-check-circle"></i> Halal Friendly
              </span>
              <h3 className="text-2xl font-bold text-gray-900 leading-tight">{recipe.title}</h3>
            </div>
            <button onClick={() => setRecipe(null)} className="text-gray-400 p-2"><i className="fas fa-times"></i></button>
          </div>

          <div className="flex gap-4 text-xs font-bold text-emerald-600 uppercase tracking-wider">
            <span><i className="fas fa-clock mr-1"></i> {recipe.prepTime}</span>
            <span><i className="fas fa-user-group mr-1"></i> {recipe.servings} Servings</span>
          </div>

          {recipe.missingIngredients.length > 0 && (
            <div className="space-y-3 bg-amber-50/50 p-4 rounded-2xl border border-amber-100">
              <h4 className="text-sm font-bold text-amber-800 flex items-center gap-2">
                <i className="fas fa-exclamation-triangle"></i> Missing Ingredients
              </h4>
              <div className="space-y-4">
                {recipe.missingIngredients.map((missing, i) => (
                  <div key={i} className="flex flex-col gap-2 bg-white p-3 rounded-xl shadow-sm border border-amber-50">
                    <div className="flex justify-between items-start">
                      <div>
                        <span className="font-bold text-gray-800 text-sm capitalize">{missing.name}</span>
                        {missing.alternative && (
                          <p className="text-[10px] text-emerald-600 font-medium mt-0.5">
                            💡 Use {missing.alternative} instead
                          </p>
                        )}
                      </div>
                    </div>
                    <div className="flex gap-2 mt-1">
                      <button 
                        onClick={() => openOrderLink(missing.name, 'chaldal')}
                        className="flex-1 bg-amber-500 text-white text-[9px] font-bold py-2 rounded-lg hover:bg-amber-600 transition-colors"
                      >
                        Chaldal
                      </button>
                      <button 
                        onClick={() => openOrderLink(missing.name, 'foodpanda')}
                        className="flex-1 bg-[#D70F64] text-white text-[9px] font-bold py-2 rounded-lg hover:opacity-90 transition-colors"
                      >
                        PandaMart
                      </button>
                      <button 
                        onClick={() => openOrderLink(missing.name, 'pathao')}
                        className="flex-1 bg-gray-800 text-white text-[9px] font-bold py-2 rounded-lg hover:bg-black transition-colors"
                      >
                        Pathao
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}

          <div className="space-y-4">
            <h4 className="font-bold text-gray-800 border-b pb-1">Steps</h4>
            <div className="space-y-4">
              {recipe.instructions.map((step, i) => (
                <div key={i} className="flex gap-3">
                  <span className="font-black text-emerald-200 text-2xl leading-none">{i+1}</span>
                  <p className="text-sm text-gray-600 flex-1">{step}</p>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

