import Footer from './components/Footer';

const App: React.FC = () => {
  const [view, setView] = useState<'dashboard' | 'logger' | 'pantry' | 'profile'>('dashboard');
  const [meals, setMeals] = useState<Meal[]>([]);
  const [pantry, setPantry] = useState<GroceryItem[]>([]);
  const [profile, setProfile] = useState<UserProfile | null>(null);
  const [isLoading, setIsLoading] = useState(false);

  useEffect(() => {
    const savedMeals = localStorage.getItem('heshel_ai_meals');
    const savedProfile = localStorage.getItem('heshel_ai_profile');
    const savedPantry = localStorage.getItem('heshel_ai_pantry');

    if (savedMeals) setMeals(JSON.parse(savedMeals));
    if (savedPantry) setPantry(JSON.parse(savedPantry));
    if (savedProfile) {
      setProfile(JSON.parse(savedProfile));
    } else {
      setView('profile');
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('heshel_ai_meals', JSON.stringify(meals));
    localStorage.setItem('heshel_ai_pantry', JSON.stringify(pantry));
    if (profile) localStorage.setItem('heshel_ai_profile', JSON.stringify(profile));
  }, [meals, pantry, profile]);

  const handleAddMeal = (meal: Meal) => {
    setMeals(prev => [meal, ...prev]);
    setView('dashboard');
  };

  const handleUpdatePantry = (items: GroceryItem[]) => {
    setPantry(items);
  };

  const handleUpdateProfile = (newProfile: UserProfile) => {
    setProfile(newProfile);
    setView('dashboard');
  };

  return (
    <div className="min-h-screen flex flex-col max-w-md mx-auto bg-white shadow-2xl relative overflow-hidden">
      <Header setView={setView} currentView={view} />

      <main className="flex-1 overflow-y-auto pb-24 scroll-smooth">
        {view === 'dashboard' && profile && (
          <Dashboard 
            meals={meals} 
            profile={profile} 
            onDeleteMeal={(id) => setMeals(m => m.filter(x => x.id !== id))}
            onAddClick={() => setView('logger')}
          />
        )}

        {view === 'logger' && (
          <MealLogger 
            onSave={handleAddMeal} 
            onCancel={() => setView('dashboard')}
            isLoading={isLoading}
            setIsLoading={setIsLoading}
          />
        )}

        {view === 'pantry' && (
          <PantryView 
            items={pantry} 
            setItems={handleUpdatePantry}
          />
        )}

        {view === 'profile' && (
          <ProfileSetup 
            profile={profile} 
            onSave={handleUpdateProfile} 
            onCancel={profile ? () => setView('dashboard') : undefined}
          />
        )}
      </main>

      <Footer setView={setView} currentView={view} />
    </div>
  );
};

export default App;

import React from 'react';
import { Meal, UserProfile, NutritionInfo } from '../types';
import { PieChart, Pie, Cell, ResponsiveContainer } from 'recharts';

interface DashboardProps {
  meals: Meal[];
  profile: UserProfile;
  onDeleteMeal: (id: string) => void;
  onAddClick: () => void;
}

const Dashboard: React.FC<DashboardProps> = ({ meals, profile, onDeleteMeal, onAddClick }) => {
  const today = new Date().setHours(0, 0, 0, 0);
  const todayMeals = meals.filter(m => m.timestamp >= today);

  const totals = todayMeals.reduce((acc, meal) => ({
    calories: acc.calories + meal.nutrition.calories,
    protein: acc.protein + meal.nutrition.protein,
    carbs: acc.carbs + meal.nutrition.carbs,
    fat: acc.fat + meal.nutrition.fat,
  }), { calories: 0, protein: 0, carbs: 0, fat: 0 });

  const remaining = Math.max(profile.dailyGoal - totals.calories, 0);

  const chartData = [
    { name: 'Consumed', value: totals.calories },
    { name: 'Remaining', value: remaining }
  ];

  const COLORS = ['#059669', '#f3f4f6'];

  return (
    <div className="p-4 space-y-6">
      <section className="bg-gradient-to-br from-emerald-600 to-emerald-700 rounded-[2.5rem] p-8 text-white shadow-2xl shadow-emerald-100/50">
        <div className="flex justify-between items-center mb-6">
          <div>
            <h2 className="text-emerald-100 text-xs font-bold uppercase tracking-widest opacity-80">Daily Energy</h2>
            <div className="text-5xl font-black mt-1">
              {totals.calories.toLocaleString()}
              <span className="text-sm font-bold text-emerald-100/50 block mt-1 tracking-normal">Goal: {profile.dailyGoal} kcal</span>
            </div>
          </div>
          <div className="h-24 w-24 relative">
             <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={chartData}
                  cx="50%"
                  cy="50%"
                  innerRadius={35}
                  outerRadius={45}
                  paddingAngle={5}
                  dataKey="value"
                  stroke="none"
                >
                  {chartData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={COLORS[index]} />
                  ))}
                </Pie>
              </PieChart>
            </ResponsiveContainer>
            <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
              <i className="fas fa-bolt text-emerald-200/50 text-xl"></i>
            </div>
          </div>
        </div>

        <div className="grid grid-cols-3 gap-6 pt-6 mt-2 border-t border-white/10">
          <div className="text-center">
            <div className="text-[10px] text-emerald-100/60 font-black uppercase tracking-widest">Protein</div>
            <div className="font-bold text-xl">{Math.round(totals.protein)}<span className="text-xs ml-0.5 opacity-60">g</span></div>
          </div>
          <div className="text-center border-x border-white/10">
            <div className="text-[10px] text-emerald-100/60 font-black uppercase tracking-widest">Carbs</div>
            <div className="font-bold text-xl">{Math.round(totals.carbs)}<span className="text-xs ml-0.5 opacity-60">g</span></div>
          </div>
          <div className="text-center">
            <div className="text-[10px] text-emerald-100/60 font-black uppercase tracking-widest">Fat</div>
            <div className="font-bold text-xl">{Math.round(totals.fat)}<span className="text-xs ml-0.5 opacity-60">g</span></div>
          </div>
        </div>
      </section>

      <section>
        <button 
          onClick={onAddClick}
          className="w-full bg-white border-2 border-dashed border-emerald-200 rounded-[2rem] p-5 flex items-center justify-center gap-4 text-emerald-700 font-bold hover:bg-emerald-50 hover:border-emerald-400 transition-all active:scale-95 group shadow-sm"
        >
          <div className="bg-emerald-100 p-3 rounded-full group-hover:bg-emerald-200 transition-colors">
            <i className="fas fa-camera-retro text-2xl"></i>
          </div>
          Log Anything Global or Local
        </button>
      </section>

      <section className="space-y-4">
        <div className="flex justify-between items-center px-2">
          <h3 className="font-black text-gray-900 tracking-tight">Timeline</h3>
          <span className="text-[10px] bg-gray-100 text-gray-500 font-bold px-2 py-0.5 rounded-full uppercase">Today</span>
        </div>

        {todayMeals.length === 0 ? (
          <div className="text-center py-16 bg-white rounded-[2rem] border border-gray-100 shadow-sm">
            <div className="bg-emerald-50 w-20 h-20 rounded-full flex items-center justify-center mx-auto mb-5 text-emerald-200">
              <i className="fas fa-plate-wheat text-3xl"></i>
            </div>
            <p className="text-gray-900 font-bold">Your timeline is empty</p>
            <p className="text-xs text-gray-400 mt-2 px-12 leading-relaxed">Heshel AI can identify everything from Panta Ilish to Mediterranean Salads.</p>
          </div>
        ) : (
          <div className="space-y-4">
            {todayMeals.map((meal) => (
