                ) : (
                  <div className="w-20 h-20 rounded-2xl bg-teal-50 flex items-center justify-center text-teal-300">
                    <i className="fas fa-utensils text-2xl"></i>
                  </div>
                )}
                <div className="flex-1 min-w-0">
                  <h4 className="font-black text-gray-900 text-lg leading-tight truncate">{meal.name}</h4>
                  <p className="text-xs text-gray-400 font-medium mt-1 uppercase tracking-wider">{new Date(meal.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })} • {meal.portionSize}</p>
                  <div className="flex gap-2 mt-3">
                    <span className="text-[9px] font-black px-2 py-1 rounded-lg bg-teal-50 text-teal-700 uppercase">P: {Math.round(meal.nutrition.protein)}g</span>
                    <span className="text-[9px] font-black px-2 py-1 rounded-lg bg-blue-50 text-blue-700 uppercase">C: {Math.round(meal.nutrition.carbs)}g</span>
                    <span className="text-[9px] font-black px-2 py-1 rounded-lg bg-rose-50 text-rose-700 uppercase">F: {Math.round(meal.nutrition.fat)}g</span>
                  </div>
                </div>
                <div className="text-right">
                  <div className="font-black text-gray-900 text-xl leading-none">{meal.nutrition.calories}</div>
                  <div className="text-[9px] text-gray-400 uppercase font-bold mt-1 tracking-widest">Kcal</div>
