import React, { useState, useEffect } from 'react';
import { Meal, UserProfile, GroceryItem } from './types';
import Dashboard from './components/Dashboard';
import MealLogger from './components/MealLogger';
import PantryView from './components/PantryView';
import ProfileSetup from './components/ProfileSetup';
import Header from './components/Header';
import Footer from './components/Footer';

const App: React.FC = () => {
  // Default view is now pantry (The core feature)
  const [view, setView] = useState<'dashboard' | 'logger' | 'pantry' | 'profile'>('pantry');
  const [meals, setMeals] = useState<Meal[]>([]);
  const [pantry, setPantry] = useState<GroceryItem[]>([]);
  const [profile, setProfile] = useState<UserProfile | null>(null);
  const [isLoading, setIsLoading] = useState(false);

  useEffect(() => {
    const savedMeals = localStorage.getItem('notripchef_meals');
    const savedProfile = localStorage.getItem('notripchef_profile');
    const savedPantry = localStorage.getItem('notripchef_pantry');

    if (savedMeals) setMeals(JSON.parse(savedMeals));
    if (savedPantry) setPantry(JSON.parse(savedPantry));
    if (savedProfile) {
      setProfile(JSON.parse(savedProfile));
    } else {
      // If no profile, we still allow pantry view but prompt for setup later
      // setView('profile'); 
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('notripchef_meals', JSON.stringify(meals));
    localStorage.setItem('notripchef_pantry', JSON.stringify(pantry));
    if (profile) localStorage.setItem('notripchef_profile', JSON.stringify(profile));
  }, [meals, pantry, profile]);

  const handleAddMeal = (meal: Meal) => {
    setMeals(prev => [meal, ...prev]);
    setView('dashboard');
  };

  return (
    <div className="min-h-screen flex flex-col max-w-md mx-auto bg-white shadow-2xl relative overflow-hidden">
      <Header setView={setView} currentView={view} />

      <main className="flex-1 overflow-y-auto pb-24 scroll-smooth">
        {view === 'pantry' && (
          <PantryView 
            items={pantry} 
            setItems={setPantry}
          />
        )}

        {view === 'dashboard' && profile && (
          <Dashboard 
            meals={meals} 
            profile={profile} 
            onDeleteMeal={(id) => setMeals(m => m.filter(x => x.id !== id))}
            onAddClick={() => setView('logger')}
          />
        )}

        {view === 'logger' && (
          <MealLogger 
            onSave={handleAddMeal} 
            onCancel={() => setView('dashboard')}
            isLoading={isLoading}
            setIsLoading={setIsLoading}
          />
        )}

        {view === 'profile' && (
          <ProfileSetup 
            profile={profile} 
            onSave={(p) => { setProfile(p); setView('pantry'); }} 
            onCancel={() => setView('pantry')}
          />
        )}
      </main>

      <Footer setView={setView} currentView={view} />
    </div>
  );
};

export default App;

import React, { useState, useRef } from 'react';
import { GroceryItem, Recipe } from '../types';
import { analyzeGroceries, generateRecipeFromGroceries } from '../services/geminiService';

interface PantryViewProps {
  items: GroceryItem[];
  setItems: (items: GroceryItem[]) => void;
}

const PantryView: React.FC<PantryViewProps> = ({ items, setItems }) => {
  const [isScanning, setIsScanning] = useState(false);
  const [isGenerating, setIsGenerating] = useState(false);
  const [recipe, setRecipe] = useState<Recipe | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleScan = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setIsScanning(true);
    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64 = (reader.result as string).split(',')[1];
      try {
        const detected = await analyzeGroceries(base64);
        // Deduplicate or just add
        setItems([...detected, ...items]);
      } catch (err) {
        alert("Pantry scan failed. Please check your connection.");
      } finally {
        setIsScanning(false);
      }
    };
    reader.readAsDataURL(file);
  };

  const handleGetRecipe = async () => {
    if (items.length === 0) {
      alert("Scan some items in your fridge first!");
      return;
    }
    setIsGenerating(true);
    try {
      const result = await generateRecipeFromGroceries(items.map(i => i.name));
      setRecipe(result);
    } catch (err) {
      alert("Recipe generation failed. Try adding more items.");
    } finally {
      setIsGenerating(false);
    }
  };

  const openOrderLink = (item: string) => {
    // Focused on the 'No Trip' philosophy - ordering if absolutely needed
    window.open(`https://www.google.com/search?q=buy+${encodeURIComponent(item)}+nearby`, '_blank');
  };

  return (
    <div className="p-5 space-y-8 animate-in fade-in duration-500">
      <section className="space-y-2">
        <h2 className="text-3xl font-extrabold text-slate-900 tracking-tight">Your Kitchen</h2>
        <p className="text-slate-500 text-sm">Magic happens with what's already here.</p>
      </section>

      <div className="bg-sage-50 rounded-[2.5rem] p-6 border border-sage-100 shadow-sm relative overflow-hidden">
        <div className="flex justify-between items-center mb-6">
          <h3 className="font-bold text-slate-800 uppercase tracking-widest text-[10px]">In-Stock Ingredients</h3>
          <span className="bg-sage-600 text-white text-[10px] font-bold px-2 py-0.5 rounded-full">{items.length} Items</span>
        </div>

        <div className="flex flex-wrap gap-2 min-h-[120px]">
          {items.length === 0 ? (
            <div className="w-full flex flex-col items-center justify-center py-8 text-slate-400/60 text-center">
              <i className="fas fa-kitchen-set text-4xl mb-3"></i>
              <p className="text-xs font-medium">Fridge is a blank canvas.<br/>Scan ingredients to start.</p>
            </div>
          ) : (
            items.map(item => (
              <div key={item.id} className="bg-white border border-slate-200 px-4 py-2 rounded-2xl shadow-sm flex items-center gap-2 group hover:border-sage-400 transition-colors">
                <span className="text-sm font-semibold text-slate-700">{item.name}</span>
                <button onClick={() => setItems(items.filter(i => i.id !== item.id))} className="text-slate-300 hover:text-rose-500 transition-colors">
                  <i className="fas fa-times-circle text-[10px]"></i>
                </button>
              </div>
            ))
          )}
        </div>

        <button 
          onClick={() => fileInputRef.current?.click()}
          className="mt-6 w-full bg-white border-2 border-dashed border-sage-200 text-sage-600 py-3 rounded-2xl font-bold text-sm flex items-center justify-center gap-2 hover:bg-sage-100 transition-all"
        >
          <i className={`fas ${isScanning ? 'fa-spinner fa-spin' : 'fa-camera'}`}></i>
          {isScanning ? 'Identifying...' : 'Add Ingredients'}
        </button>
        <input type="file" className="hidden" ref={fileInputRef} onChange={handleScan} accept="image/*" />
      </div>

      <button 
        onClick={handleGetRecipe}
        disabled={isGenerating || items.length === 0}
        className="w-full bg-slate-900 text-white font-bold py-5 rounded-[2rem] shadow-xl shadow-slate-200 flex items-center justify-center gap-3 active:scale-95 transition-all disabled:opacity-50"
      >
        {isGenerating ? (
          <><i className="fas fa-hat-chef fa-spin"></i> Finding a Recipe...</>
        ) : (
          <><i className="fas fa-wand-magic-sparkles"></i> Generate No-Trip Recipe</>
        )}
      </button>

      {recipe && (
        <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-2xl p-7 space-y-6 animate-in slide-in-from-bottom-10 duration-700">
          <div className="flex justify-between items-start">
            <div className="flex-1 pr-4">
              <div className="flex items-center gap-2 mb-2">
                <span className="bg-emerald-100 text-emerald-700 text-[9px] font-black px-2 py-0.5 rounded-full uppercase tracking-widest">
                  {recipe.missingIngredients.length === 0 ? 'TRIP NOT NEEDED' : 'NEARLY READY'}
                </span>
                <span className="text-slate-300">|</span>
                <span className="text-slate-400 text-[10px] font-bold uppercase">{recipe.prepTime}</span>
              </div>
              <h3 className="text-2xl font-black text-slate-900 leading-tight">{recipe.title}</h3>
            </div>
            <button onClick={() => setRecipe(null)} className="bg-slate-50 text-slate-400 w-8 h-8 rounded-full flex items-center justify-center"><i className="fas fa-times"></i></button>
          </div>

          <p className="text-slate-500 text-sm italic leading-relaxed">"{recipe.description}"</p>

          {recipe.missingIngredients.length > 0 && (
            <div className="bg-amber-50 rounded-3xl p-5 border border-amber-100 space-y-3">
              <h4 className="text-[10px] font-black text-amber-800 uppercase tracking-widest flex items-center gap-2">
                <i className="fas fa-route"></i> Minimal Trip Items
              </h4>
              <div className="flex flex-wrap gap-2">
                {recipe.missingIngredients.map((missing, i) => (
                  <div key={i} className="bg-white px-3 py-1.5 rounded-xl text-xs font-bold text-slate-700 border border-amber-200 shadow-sm flex items-center gap-2">
                    {missing.name}
                    {missing.alternative && (
                      <span className="text-[10px] text-emerald-600 font-medium">Or: {missing.alternative}</span>
                    )}
                  </div>
                ))}
              </div>
              <button 
                onClick={() => openOrderLink(recipe.missingIngredients[0].name)}
                className="text-[10px] font-black text-amber-700 underline uppercase mt-2 block"
              >
                Order Missing Items Instantly
              </button>
            </div>
          )}

          <div className="space-y-4">
            <h4 className="font-black text-slate-900 text-xs uppercase tracking-widest border-b border-slate-100 pb-2">Chef's Steps</h4>
            <div className="space-y-6">
              {recipe.instructions.map((step, i) => (
                <div key={i} className="flex gap-4 items-start">
                  <div className="bg-slate-900 text-white w-6 h-6 rounded-lg flex items-center justify-center text-[10px] font-bold flex-shrink-0 mt-0.5">{i+1}</div>
                  <p className="text-sm text-slate-600 leading-relaxed">{step}</p>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

