import React from 'react';
import { Meal, UserProfile } from '../types';
import { PieChart, Pie, Cell, ResponsiveContainer } from 'recharts';

interface DashboardProps {
  meals: Meal[];
  profile: UserProfile;
  onDeleteMeal: (id: string) => void;
  onAddClick: () => void;
}

const Dashboard: React.FC<DashboardProps> = ({ meals, profile, onDeleteMeal, onAddClick }) => {
  const today = new Date().setHours(0, 0, 0, 0);
  const todayMeals = meals.filter(m => m.timestamp >= today);

  const totals = todayMeals.reduce((acc, meal) => ({
    calories: acc.calories + meal.nutrition.calories,
    protein: acc.protein + meal.nutrition.protein,
    carbs: acc.carbs + meal.nutrition.carbs,
    fat: acc.fat + meal.nutrition.fat,
  }), { calories: 0, protein: 0, carbs: 0, fat: 0 });

  const remaining = Math.max(profile.dailyGoal - totals.calories, 0);
  const chartData = [{ name: 'C', value: totals.calories }, { name: 'R', value: remaining }];
  const COLORS = ['#52796f', '#f1f5f9'];

  return (
    <div className="p-5 space-y-6 animate-in fade-in slide-in-from-bottom-5">
      <h2 className="text-3xl font-extrabold text-slate-900 tracking-tight">Wellness Stats</h2>

      <section className="bg-white border border-slate-100 rounded-[2.5rem] p-8 shadow-xl shadow-slate-100 flex items-center justify-between">
        <div>
          <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Daily Energy</h3>
          <div className="text-4xl font-black text-slate-900 leading-none">
            {totals.calories} <span className="text-xs text-slate-300 uppercase">kcal</span>
          </div>
          <p className="text-[10px] font-bold text-sage-600 mt-2">Target: {profile.dailyGoal} kcal</p>
        </div>
        <div className="w-20 h-20">
          <ResponsiveContainer width="100%" height="100%">
            <PieChart>
              <Pie data={chartData} innerRadius={25} outerRadius={35} paddingAngle={5} dataKey="value" stroke="none">
                {chartData.map((_, i) => <Cell key={i} fill={COLORS[i]} />)}
              </Pie>
            </PieChart>
          </ResponsiveContainer>
        </div>
      </section>

      <div className="grid grid-cols-3 gap-3">
        <div className="bg-slate-50 p-4 rounded-3xl text-center border border-slate-100">
          <span className="text-[9px] font-black text-slate-400 uppercase">Protein</span>
          <div className="text-lg font-black text-slate-800">{Math.round(totals.protein)}g</div>
        </div>
        <div className="bg-slate-50 p-4 rounded-3xl text-center border border-slate-100">
          <span className="text-[9px] font-black text-slate-400 uppercase">Carbs</span>
          <div className="text-lg font-black text-slate-800">{Math.round(totals.carbs)}g</div>
        </div>
        <div className="bg-slate-50 p-4 rounded-3xl text-center border border-slate-100">
          <span className="text-[9px] font-black text-slate-400 uppercase">Fat</span>
          <div className="text-lg font-black text-slate-800">{Math.round(totals.fat)}g</div>
        </div>
      </div>

      <button 
        onClick={onAddClick}
        className="w-full bg-sage-50 border-2 border-dashed border-sage-200 text-sage-700 font-black py-4 rounded-[1.5rem] flex items-center justify-center gap-3"
      >
        <i className="fas fa-camera"></i> Log a Meal for Calories
      </button>

      <div className="space-y-4 pt-4">
        <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-2">Today's Meal Log</h4>
        {todayMeals.length === 0 ? (
          <p className="text-center py-10 text-slate-300 text-sm italic">Wellness tracking is optional. Start logging when ready.</p>
        ) : (
          todayMeals.map(meal => (
            <div key={meal.id} className="bg-white p-4 rounded-[1.5rem] flex items-center gap-4 border border-slate-100 shadow-sm relative group">
              {meal.image && <img src={meal.image} className="w-14 h-14 rounded-xl object-cover" />}
              <div className="flex-1 min-w-0">
                <h4 className="font-bold text-slate-900 truncate">{meal.name}</h4>
                <div className="text-[10px] font-black text-slate-400 uppercase">{meal.nutrition.calories} Kcal</div>
              </div>
              <button onClick={() => onDeleteMeal(meal.id)} className="text-slate-200 hover:text-rose-500 transition-colors">
                <i className="fas fa-trash-can text-xs"></i>
              </button>
            </div>
          ))
        )}
      </div>
    </div>
  );
};

