import React, { useState, useEffect } from 'react';
import { Meal, UserProfile, GroceryItem } from './types';
import Dashboard from './components/Dashboard';
import MealLogger from './components/MealLogger';
import PantryView from './components/PantryView';
import ProfileSetup from './components/ProfileSetup';
import Header from './components/Header';
import Footer from './components/Footer';

const App: React.FC = () => {
  const [view, setView] = useState<'dashboard' | 'logger' | 'pantry' | 'profile'>('pantry');
  const [meals, setMeals] = useState<Meal[]>([]);
  const [pantry, setPantry] = useState<GroceryItem[]>([]);
  const [profile, setProfile] = useState<UserProfile | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [deferredPrompt, setDeferredPrompt] = useState<any>(null);

  useEffect(() => {
    const savedMeals = localStorage.getItem('notripchef_meals');
    const savedProfile = localStorage.getItem('notripchef_profile');
    const savedPantry = localStorage.getItem('notripchef_pantry');

    if (savedMeals) setMeals(JSON.parse(savedMeals));
    if (savedPantry) setPantry(JSON.parse(savedPantry));
    if (savedProfile) setProfile(JSON.parse(savedProfile));

    // Handle PWA Install Prompt
    window.addEventListener('beforeinstallprompt', (e) => {
      e.preventDefault();
      setDeferredPrompt(e);
    });
  }, []);

  useEffect(() => {
    localStorage.setItem('notripchef_meals', JSON.stringify(meals));
    localStorage.setItem('notripchef_pantry', JSON.stringify(pantry));
    if (profile) localStorage.setItem('notripchef_profile', JSON.stringify(profile));
  }, [meals, pantry, profile]);

  const handleInstall = async () => {
    if (deferredPrompt) {
      deferredPrompt.prompt();
      const { outcome } = await deferredPrompt.userChoice;
      if (outcome === 'accepted') setDeferredPrompt(null);
    }
  };

  const handleAddMeal = (meal: Meal) => {
    setMeals(prev => [meal, ...prev]);
    setView('dashboard');
  };

  return (
    <div className="min-h-screen flex flex-col max-w-md mx-auto bg-white shadow-2xl relative overflow-hidden">
      <Header setView={setView} currentView={view} />

      <main className="flex-1 overflow-y-auto pb-24 scroll-smooth">
        {view === 'pantry' && (
          <PantryView 
            items={pantry} 
            setItems={setPantry}
          />
        )}

        {view === 'dashboard' && profile && (
          <Dashboard 
            meals={meals} 
            profile={profile} 
            onDeleteMeal={(id) => setMeals(m => m.filter(x => x.id !== id))}
            onAddClick={() => setView('logger')}
          />
        )}

        {view === 'logger' && (
          <MealLogger 
            onSave={handleAddMeal} 
            onCancel={() => setView('dashboard')}
            isLoading={isLoading}
            setIsLoading={setIsLoading}
          />
        )}

        {view === 'profile' && (
          <ProfileSetup 
            profile={profile} 
            onSave={(p) => { setProfile(p); setView('pantry'); }} 
            onCancel={() => setView('pantry')}
            onInstall={deferredPrompt ? handleInstall : undefined}
          />
        )}
      </main>

      <Footer setView={setView} currentView={view} />
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { UserProfile } from '../types';

interface ProfileSetupProps {
  profile: UserProfile | null;
  onSave: (profile: UserProfile) => void;
  onCancel?: () => void;
  onInstall?: () => void;
}

const ProfileSetup: React.FC<ProfileSetupProps> = ({ profile, onSave, onCancel, onInstall }) => {
  const [formData, setFormData] = useState<UserProfile>(profile || {
    name: '',
    weight: 70,
    height: 170,
    age: 25,
    gender: 'male',
    activityLevel: 'moderate',
    dailyGoal: 2000
  });

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: name === 'gender' || name === 'activityLevel' || name === 'name' ? value : Number(value)
    }));
  };

  const calculateSuggestedCalories = () => {
    let bmr = 0;
    if (formData.gender === 'male') {
      bmr = 10 * formData.weight + 6.25 * formData.height - 5 * formData.age + 5;
    } else {
      bmr = 10 * formData.weight + 6.25 * formData.height - 5 * formData.age - 161;
    }
    const multipliers = { sedentary: 1.2, light: 1.375, moderate: 1.55, active: 1.725 };
    const tdee = bmr * multipliers[formData.activityLevel];
    setFormData(prev => ({ ...prev, dailyGoal: Math.round(tdee) }));
  };

  return (
    <div className="p-6 space-y-8 pb-32">
      <div>
        <h2 className="text-3xl font-black text-slate-900 tracking-tight">Settings</h2>
        <p className="text-slate-500 text-sm">Personalize your NoTripChef experience.</p>
      </div>

      {onInstall && (
        <section className="bg-slate-900 rounded-3xl p-6 text-white shadow-xl shadow-slate-200 animate-pulse-soft">
          <div className="flex items-center gap-4 mb-4">
            <div className="bg-sage-600 w-12 h-12 rounded-2xl flex items-center justify-center">
              <i className="fas fa-download text-xl"></i>
            </div>
            <div>
              <h4 className="font-bold">Add to Home Screen</h4>
              <p className="text-[10px] text-slate-400 uppercase font-black tracking-widest">Native Experience</p>
            </div>
          </div>
          <button 
            onClick={onInstall}
            className="w-full bg-white text-slate-900 font-bold py-3 rounded-xl hover:bg-sage-50 transition-colors"
          >
            Install NoTripChef
          </button>
        </section>
      )}

      <div className="space-y-6">
        <div className="space-y-4">
          <div>
            <label className="block text-[10px] font-black text-slate-400 uppercase mb-2 ml-1 tracking-widest">Chef Name</label>
            <input 
              type="text" 
              name="name" 
              value={formData.name} 
              onChange={handleChange}
              placeholder="Your Name"
              className="w-full bg-slate-50 border border-slate-100 rounded-2xl px-5 py-4 focus:ring-2 focus:ring-sage-600 focus:outline-none font-semibold"
            />
          </div>

          <div className="pt-6 border-t border-slate-100">
            <h4 className="text-[10px] font-black text-slate-400 uppercase mb-4 ml-1 tracking-widest">Body Stats (Optional)</h4>
            <div className="grid grid-cols-2 gap-4 mb-4">
              <div>
                <label className="block text-[10px] font-bold text-slate-400 uppercase mb-2 ml-1">Weight (kg)</label>
                <input type="number" name="weight" value={formData.weight} onChange={handleChange} className="w-full bg-slate-50 border border-slate-100 rounded-2xl px-4 py-3" />
              </div>
              <div>
                <label className="block text-[10px] font-bold text-slate-400 uppercase mb-2 ml-1">Height (cm)</label>
                <input type="number" name="height" value={formData.height} onChange={handleChange} className="w-full bg-slate-50 border border-slate-100 rounded-2xl px-4 py-3" />
              </div>
            </div>

            <div className="flex justify-between items-center mb-2 px-1">
              <label className="block text-[10px] font-black text-slate-400 uppercase">Calorie Goal</label>
              <button onClick={calculateSuggestedCalories} className="text-sage-600 text-[10px] font-black uppercase tracking-wider">Auto-Calc</button>
            </div>
            <input 
              type="number" 
              name="dailyGoal" 
              value={formData.dailyGoal} 
              onChange={handleChange}
              className="w-full bg-sage-50 border border-sage-100 rounded-2xl px-5 py-5 text-sage-900 font-black text-2xl"
            />
          </div>
        </div>

        <div className="flex gap-3 pt-6">
          {onCancel && (
            <button onClick={onCancel} className="flex-1 bg-slate-100 text-slate-500 font-bold py-4 rounded-2xl">Cancel</button>
          )}
          <button 
            onClick={() => onSave(formData)}
            className="flex-[2] bg-sage-600 text-white font-bold py-4 rounded-2xl shadow-lg shadow-sage-100"
          >
            Save Profile
          </button>
        </div>
      </div>
    </div>
  );
};

export default ProfileSetup;

