import React, { useState, useRef } from 'react';
import { GroceryItem, Recipe } from '../types';
import { analyzeGroceries, generateRecipeFromGroceries } from '../services/geminiService';

interface PantryViewProps {
  items: GroceryItem[];
  setItems: (items: GroceryItem[]) => void;
}

const PantryView: React.FC<PantryViewProps> = ({ items, setItems }) => {
  const [isScanning, setIsScanning] = useState(false);
  const [isGenerating, setIsGenerating] = useState(false);
  const [recipe, setRecipe] = useState<Recipe | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleScan = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setIsScanning(true);
    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64 = (reader.result as string).split(',')[1];
      try {
        const detected = await analyzeGroceries(base64);
        setItems([...detected, ...items]);
      } catch (err) {
        alert("Pantry scan failed. Please check your connection.");
      } finally {
        setIsScanning(false);
      }
    };
    reader.readAsDataURL(file);
  };

  const handleGetRecipe = async () => {
    if (items.length === 0) {
      alert("Scan some items in your fridge first!");
      return;
    }
    setIsGenerating(true);
    try {
      const result = await generateRecipeFromGroceries(items.map(i => i.name));
      setRecipe(result);
    } catch (err) {
      alert("Recipe generation failed. Try adding more items.");
    } finally {
      setIsGenerating(false);
    }
  };

  const openOrderLink = (item: string) => {
    window.open(`https://www.google.com/search?q=buy+${encodeURIComponent(item)}+nearby`, '_blank');
  };

  return (
    <div className="p-5 space-y-8 animate-in fade-in duration-500">
      <section className="space-y-2">
        <h2 className="text-3xl font-extrabold text-zinc-100 tracking-tight">Your Kitchen</h2>
        <p className="text-zinc-500 text-sm">Everything you need is already here.</p>
      </section>

      <div className="bg-zinc-900 rounded-[2.5rem] p-6 border border-zinc-800 shadow-sm relative overflow-hidden">
        <div className="flex justify-between items-center mb-6">
          <h3 className="font-bold text-zinc-400 uppercase tracking-widest text-[10px]">In-Stock Ingredients</h3>
          <span className="bg-zinc-800 text-zinc-300 text-[10px] font-bold px-3 py-1 rounded-full border border-zinc-700">{items.length} Items</span>
        </div>

        <div className="flex flex-wrap gap-2 min-h-[120px]">
          {items.length === 0 ? (
            <div className="w-full flex flex-col items-center justify-center py-8 text-zinc-700 text-center">
              <i className="fas fa-kitchen-set text-4xl mb-3 opacity-20"></i>
              <p className="text-xs font-medium opacity-50">Empty pantry.<br/>Snap a photo to fill it.</p>
            </div>
          ) : (
            items.map(item => (
              <div key={item.id} className="bg-zinc-800 border border-zinc-700 px-4 py-2 rounded-2xl shadow-sm flex items-center gap-2 group hover:border-zinc-500 transition-colors">
                <span className="text-sm font-semibold text-zinc-300">{item.name}</span>
                <button onClick={() => setItems(items.filter(i => i.id !== item.id))} className="text-zinc-600 hover:text-rose-500 transition-colors">
                  <i className="fas fa-times-circle text-[10px]"></i>
                </button>
              </div>
            ))
          )}
        </div>

        <button 
          onClick={() => fileInputRef.current?.click()}
          className="mt-6 w-full bg-zinc-950 border-2 border-dashed border-zinc-800 text-zinc-500 py-3 rounded-2xl font-bold text-sm flex items-center justify-center gap-2 hover:bg-zinc-900 hover:text-zinc-300 transition-all"
        >
          <i className={`fas ${isScanning ? 'fa-spinner fa-spin' : 'fa-camera'}`}></i>
          {isScanning ? 'Identifying...' : 'Update Pantry'}
        </button>
        <input type="file" className="hidden" ref={fileInputRef} onChange={handleScan} accept="image/*" />
      </div>

      <button 
        onClick={handleGetRecipe}
        disabled={isGenerating || items.length === 0}
        className="w-full bg-zinc-100 text-zinc-950 font-black py-5 rounded-[2rem] shadow-xl shadow-white/5 flex items-center justify-center gap-3 active:scale-95 transition-all disabled:opacity-30"
      >
        {isGenerating ? (
          <><i className="fas fa-hat-chef fa-spin"></i> Finding a Recipe...</>
        ) : (
          <><i className="fas fa-wand-magic-sparkles"></i> Magic Recipe</>
        )}
      </button>

      {recipe && (
        <div className="bg-zinc-900 rounded-[2.5rem] border border-zinc-800 shadow-2xl p-7 space-y-6 animate-in slide-in-from-bottom-10 duration-700">
          <div className="flex justify-between items-start">
            <div className="flex-1 pr-4">
              <div className="flex items-center gap-2 mb-2">
                <span className="bg-zinc-800 text-zinc-300 text-[9px] font-black px-2 py-0.5 rounded-full uppercase tracking-widest border border-zinc-700">
                  {recipe.missingIngredients.length === 0 ? 'TRIP NOT NEEDED' : 'NEARLY READY'}
                </span>
                <span className="text-zinc-700">|</span>
                <span className="text-zinc-500 text-[10px] font-bold uppercase">{recipe.prepTime}</span>
              </div>
              <h3 className="text-2xl font-black text-zinc-100 leading-tight">{recipe.title}</h3>
            </div>
            <button onClick={() => setRecipe(null)} className="bg-zinc-800 text-zinc-500 w-8 h-8 rounded-full flex items-center justify-center border border-zinc-700"><i className="fas fa-times"></i></button>
          </div>

          <p className="text-zinc-500 text-sm italic leading-relaxed">"{recipe.description}"</p>

          {recipe.missingIngredients.length > 0 && (
            <div className="bg-zinc-950 rounded-3xl p-5 border border-zinc-800 space-y-3">
              <h4 className="text-[10px] font-black text-zinc-500 uppercase tracking-widest flex items-center gap-2">
                <i className="fas fa-route"></i> Essential Additions
              </h4>
              <div className="flex flex-wrap gap-2">
                {recipe.missingIngredients.map((missing, i) => (
                  <div key={i} className="bg-zinc-900 px-3 py-1.5 rounded-xl text-xs font-bold text-zinc-400 border border-zinc-800 shadow-sm flex items-center gap-2">
                    {missing.name}
                    {missing.alternative && (
                      <span className="text-[10px] text-zinc-600 font-medium">Alt: {missing.alternative}</span>
                    )}
                  </div>
                ))}
              </div>
            </div>
          )}

          <div className="space-y-4">
            <h4 className="font-black text-zinc-500 text-xs uppercase tracking-widest border-b border-zinc-800 pb-2">Chef's Steps</h4>
            <div className="space-y-6">
              {recipe.instructions.map((step, i) => (
                <div key={i} className="flex gap-4 items-start">
                  <div className="bg-zinc-100 text-zinc-950 w-6 h-6 rounded-lg flex items-center justify-center text-[10px] font-bold flex-shrink-0 mt-0.5">{i+1}</div>
                  <p className="text-sm text-zinc-400 leading-relaxed">{step}</p>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

