import React from 'react';
import { Meal, UserProfile } from '../types';
import { PieChart, Pie, Cell, ResponsiveContainer } from 'recharts';

interface DashboardProps {
  meals: Meal[];
  profile: UserProfile;
  onDeleteMeal: (id: string) => void;
  onAddClick: () => void;
}

const Dashboard: React.FC<DashboardProps> = ({ meals, profile, onDeleteMeal, onAddClick }) => {
  const today = new Date().setHours(0, 0, 0, 0);
  const todayMeals = meals.filter(m => m.timestamp >= today);

  const totals = todayMeals.reduce((acc, meal) => ({
    calories: acc.calories + meal.nutrition.calories,
    protein: acc.protein + meal.nutrition.protein,
    carbs: acc.carbs + meal.nutrition.carbs,
    fat: acc.fat + meal.nutrition.fat,
  }), { calories: 0, protein: 0, carbs: 0, fat: 0 });

  const remaining = Math.max(profile.dailyGoal - totals.calories, 0);
  const chartData = [{ name: 'C', value: totals.calories }, { name: 'R', value: remaining }];
  const COLORS = ['#e4e4e7', '#18181b'];

  return (
    <div className="p-5 space-y-6 animate-in fade-in slide-in-from-bottom-5">
      <h2 className="text-3xl font-extrabold text-zinc-100 tracking-tight">Wellness</h2>

      <section className="bg-zinc-900 border border-zinc-800 rounded-[2.5rem] p-8 shadow-xl flex items-center justify-between">
        <div>
          <h3 className="text-[10px] font-black text-zinc-500 uppercase tracking-widest mb-1">Energy Balance</h3>
          <div className="text-4xl font-black text-zinc-100 leading-none">
            {totals.calories} <span className="text-xs text-zinc-600 uppercase">kcal</span>
          </div>
          <p className="text-[10px] font-bold text-zinc-400 mt-2">Daily Goal: {profile.dailyGoal}</p>
        </div>
        <div className="w-20 h-20">
          <ResponsiveContainer width="100%" height="100%">
            <PieChart>
              <Pie data={chartData} innerRadius={28} outerRadius={36} paddingAngle={2} dataKey="value" stroke="none">
                {chartData.map((_, i) => <Cell key={i} fill={COLORS[i]} />)}
              </Pie>
            </PieChart>
          </ResponsiveContainer>
        </div>
      </section>

      <div className="grid grid-cols-3 gap-3">
        <div className="bg-zinc-900 p-4 rounded-3xl text-center border border-zinc-800">
          <span className="text-[9px] font-black text-zinc-600 uppercase">Protein</span>
          <div className="text-lg font-black text-zinc-300">{Math.round(totals.protein)}g</div>
        </div>
        <div className="bg-zinc-900 p-4 rounded-3xl text-center border border-zinc-800">
          <span className="text-[9px] font-black text-zinc-600 uppercase">Carbs</span>
          <div className="text-lg font-black text-zinc-300">{Math.round(totals.carbs)}g</div>
        </div>
        <div className="bg-zinc-900 p-4 rounded-3xl text-center border border-zinc-800">
          <span className="text-[9px] font-black text-zinc-600 uppercase">Fat</span>
          <div className="text-lg font-black text-zinc-300">{Math.round(totals.fat)}g</div>
        </div>
      </div>

      <button 
        onClick={onAddClick}
        className="w-full bg-zinc-900 border border-zinc-800 text-zinc-400 font-black py-4 rounded-[1.5rem] flex items-center justify-center gap-3 hover:text-zinc-100 transition-colors"
      >
        <i className="fas fa-camera"></i> Log Intake
      </button>

      <div className="space-y-4 pt-4">
        <h4 className="text-[10px] font-black text-zinc-500 uppercase tracking-widest px-2">History</h4>
        {todayMeals.length === 0 ? (
          <p className="text-center py-10 text-zinc-700 text-sm italic">No entries yet.</p>
        ) : (
          todayMeals.map(meal => (
            <div key={meal.id} className="bg-zinc-900 p-4 rounded-[1.5rem] flex items-center gap-4 border border-zinc-800 shadow-sm relative group">
              {meal.image && <img src={meal.image} className="w-14 h-14 rounded-xl object-cover grayscale opacity-70" />}
              <div className="flex-1 min-w-0">
                <h4 className="font-bold text-zinc-300 truncate">{meal.name}</h4>
                <div className="text-[10px] font-black text-zinc-600 uppercase">{meal.nutrition.calories} Kcal</div>
              </div>
              <button onClick={() => onDeleteMeal(meal.id)} className="text-zinc-700 hover:text-rose-900 transition-colors">
                <i className="fas fa-trash-can text-xs"></i>
              </button>
            </div>
          ))
        )}
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';
import { UserProfile } from '../types';

interface ProfileSetupProps {
  profile: UserProfile | null;
  onSave: (profile: UserProfile) => void;
  onCancel?: () => void;
  onInstall?: () => void;
}

const ProfileSetup: React.FC<ProfileSetupProps> = ({ profile, onSave, onCancel, onInstall }) => {
  const [formData, setFormData] = useState<UserProfile>(profile || {
    name: '',
    weight: 70,
    height: 170,
    age: 25,
    gender: 'male',
    activityLevel: 'moderate',
    dailyGoal: 2000
  });

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: name === 'gender' || name === 'activityLevel' || name === 'name' ? value : Number(value)
    }));
  };

  const calculateSuggestedCalories = () => {
    let bmr = 0;
    if (formData.gender === 'male') {
      bmr = 10 * formData.weight + 6.25 * formData.height - 5 * formData.age + 5;
    } else {
      bmr = 10 * formData.weight + 6.25 * formData.height - 5 * formData.age - 161;
    }
    const multipliers = { sedentary: 1.2, light: 1.375, moderate: 1.55, active: 1.725 };
    const tdee = bmr * multipliers[formData.activityLevel];
    setFormData(prev => ({ ...prev, dailyGoal: Math.round(tdee) }));
  };

  return (
    <div className="p-6 space-y-8 pb-32">
      <div>
        <h2 className="text-3xl font-black text-zinc-100 tracking-tight">Settings</h2>
        <p className="text-zinc-500 text-sm">Fine-tune your NoTripChef engine.</p>
      </div>

      {onInstall && (
        <section className="bg-zinc-100 rounded-3xl p-6 text-zinc-950 shadow-xl shadow-white/5 animate-pulse-soft">
          <div className="flex items-center gap-4 mb-4">
            <div className="bg-zinc-950 w-12 h-12 rounded-2xl flex items-center justify-center text-zinc-100">
              <i className="fas fa-download text-xl"></i>
            </div>
            <div>
              <h4 className="font-bold">Offline Access</h4>
              <p className="text-[10px] text-zinc-500 uppercase font-black tracking-widest">Install to device</p>
            </div>
          </div>
          <button 
            onClick={onInstall}
            className="w-full bg-zinc-950 text-zinc-100 font-bold py-3 rounded-xl hover:bg-zinc-800 transition-colors"
          >
            Install App
          </button>
        </section>
      )}

      <div className="space-y-6">
        <div className="space-y-4">
          <div>
            <label className="block text-[10px] font-black text-zinc-500 uppercase mb-2 ml-1 tracking-widest">Chef Handle</label>
            <input 
              type="text" 
              name="name" 
              value={formData.name} 
              onChange={handleChange}
              placeholder="Your Name"
              className="w-full bg-zinc-900 border border-zinc-800 rounded-2xl px-5 py-4 focus:ring-1 focus:ring-zinc-500 focus:outline-none font-semibold text-zinc-100 placeholder-zinc-700"
            />
          </div>

          <div className="pt-6 border-t border-zinc-800">
            <h4 className="text-[10px] font-black text-zinc-500 uppercase mb-4 ml-1 tracking-widest">Body Metrics</h4>
            <div className="grid grid-cols-2 gap-4 mb-4">
              <div>
                <label className="block text-[10px] font-bold text-zinc-600 uppercase mb-2 ml-1">Weight (kg)</label>
                <input type="number" name="weight" value={formData.weight} onChange={handleChange} className="w-full bg-zinc-900 border border-zinc-800 rounded-2xl px-4 py-3 text-zinc-100" />
              </div>
              <div>
                <label className="block text-[10px] font-bold text-zinc-600 uppercase mb-2 ml-1">Height (cm)</label>
                <input type="number" name="height" value={formData.height} onChange={handleChange} className="w-full bg-zinc-900 border border-zinc-800 rounded-2xl px-4 py-3 text-zinc-100" />
              </div>
            </div>

            <div className="flex justify-between items-center mb-2 px-1">
              <label className="block text-[10px] font-black text-zinc-500 uppercase">Calorie Target</label>
              <button onClick={calculateSuggestedCalories} className="text-zinc-400 text-[10px] font-black uppercase tracking-wider hover:text-zinc-100">Auto-Tune</button>
            </div>
            <input 
              type="number" 
              name="dailyGoal" 
              value={formData.dailyGoal} 
              onChange={handleChange}
              className="w-full bg-zinc-900 border border-zinc-800 rounded-2xl px-5 py-5 text-zinc-100 font-black text-2xl"
            />
          </div>
        </div>

        <div className="flex gap-3 pt-6">
          {onCancel && (
            <button onClick={onCancel} className="flex-1 bg-zinc-900 text-zinc-600 font-bold py-4 rounded-2xl border border-zinc-800">Cancel</button>
          )}
          <button 
            onClick={() => onSave(formData)}
            className="flex-[2] bg-zinc-100 text-zinc-950 font-bold py-4 rounded-2xl shadow-xl shadow-white/5 active:scale-95 transition-all"
          >
            Confirm Changes
          </button>
        </div>
      </div>
    </div>
  );
};

export default ProfileSetup;

import React, { useState, useRef } from 'react';
import { analyzeMealImage } from '../services/geminiService';
import { Meal, FoodAnalysisResult } from '../types';

interface MealLoggerProps {
  onSave: (meal: Meal) => void;
  onCancel: () => void;
  isLoading: boolean;
  setIsLoading: (loading: boolean) => void;
}

const MealLogger: React.FC<MealLoggerProps> = ({ onSave, onCancel, isLoading, setIsLoading }) => {
  const [capturedImage, setCapturedImage] = useState<string | null>(null);
  const [analysis, setAnalysis] = useState<FoodAnalysisResult | null>(null);
  const [userContext] = useState('');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64 = reader.result as string;
        setCapturedImage(base64);
        handleAnalyze(base64);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleAnalyze = async (image: string) => {
    setIsLoading(true);
    try {
      const base64Data = image.split(',')[1];
      const result = await analyzeMealImage(base64Data, userContext);
      setAnalysis(result);
    } catch (error) {
      console.error(error);
      alert("Analysis failed. Please try again.");
    } finally {
      setIsLoading(false);
    }
  };

  const handleConfirmSave = () => {
    if (analysis) {
      const newMeal: Meal = {
        id: Date.now().toString(),
        name: analysis.foodName,
        timestamp: Date.now(),
        image: capturedImage || undefined,
        nutrition: analysis.estimatedNutrition,
        ingredients: analysis.ingredientsFound,
        portionSize: analysis.suggestedPortion
      };
      onSave(newMeal);
    }
  };

  return (
    <div className="p-4 flex flex-col min-h-full">
      <div className="flex items-center justify-between mb-6">
        <button onClick={onCancel} className="text-zinc-600 hover:text-zinc-300">
          <i className="fas fa-chevron-left mr-1"></i> Back
        </button>
        <h2 className="font-bold text-xl text-zinc-100 tracking-tight">Food Vision</h2>
        <div className="w-8"></div>
      </div>

      {!capturedImage ? (
        <div className="flex-1 flex flex-col items-center justify-center space-y-8">
          <div className="w-full max-w-[280px] aspect-square bg-zinc-900 border-2 border-dashed border-zinc-800 rounded-3xl flex flex-col items-center justify-center text-center p-6 space-y-4">
            <div className="w-20 h-20 bg-zinc-800 text-zinc-500 rounded-full flex items-center justify-center text-3xl border border-zinc-700">
              <i className="fas fa-camera"></i>
            </div>
            <div>
              <p className="font-bold text-zinc-300">Analyze Meal</p>
              <p className="text-xs text-zinc-600 mt-2 px-4">Identify nutrients and ingredients instantly via camera.</p>
            </div>
          </div>

          <div className="w-full space-y-3">
            <button 
              onClick={() => fileInputRef.current?.click()}
              className="w-full bg-zinc-100 text-zinc-950 font-bold py-4 rounded-2xl shadow-xl shadow-white/5 flex items-center justify-center gap-2"
            >
              <i className="fas fa-camera"></i>
              Open Lens
            </button>
            <input 
              type="file" 
              accept="image/*" 
              className="hidden" 
              ref={fileInputRef} 
              onChange={handleFileChange}
            />
          </div>
        </div>
      ) : (
        <div className="space-y-6">
          <div className="relative group overflow-hidden rounded-3xl shadow-lg border border-zinc-800">
            <img src={capturedImage} alt="Captured meal" className="w-full h-64 object-cover grayscale opacity-80" />
            {isLoading && (
              <div className="absolute inset-0 bg-zinc-950/60 backdrop-blur-sm flex flex-col items-center justify-center text-zinc-100 p-6 text-center">
                <div className="w-12 h-12 border-4 border-zinc-100 border-t-transparent rounded-full animate-spin mb-4"></div>
                <p className="font-bold text-lg">Analyzing...</p>
                <p className="text-sm opacity-60 mt-1 uppercase tracking-widest text-[10px]">Processing Image Data</p>
              </div>
            )}
          </div>

          {!isLoading && analysis && (
            <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-500">
              <div className="bg-zinc-900 rounded-2xl p-6 border border-zinc-800">
                <div className="flex justify-between items-start mb-4">
                  <h3 className="text-2xl font-black text-zinc-100 leading-tight">{analysis.foodName}</h3>
                  <div className="bg-zinc-800 border border-zinc-700 px-2 py-0.5 rounded text-[10px] font-bold text-zinc-400">
                    MATCH CONFIRMED
                  </div>
                </div>

                <div className="grid grid-cols-4 gap-2">
                  <div className="bg-zinc-950 border border-zinc-800 p-3 rounded-xl text-center shadow-sm">
                    <div className="text-[9px] text-zinc-600 uppercase font-black">Kcal</div>
                    <div className="font-bold text-zinc-100 text-lg">{analysis.estimatedNutrition.calories}</div>
                  </div>
                  <div className="bg-zinc-950 border border-zinc-800 p-3 rounded-xl text-center shadow-sm">
                    <div className="text-[9px] text-zinc-600 uppercase font-black">P</div>
                    <div className="font-bold text-zinc-400 text-lg">{Math.round(analysis.estimatedNutrition.protein)}g</div>
                  </div>
                  <div className="bg-zinc-950 border border-zinc-800 p-3 rounded-xl text-center shadow-sm">
                    <div className="text-[9px] text-zinc-600 uppercase font-black">C</div>
                    <div className="font-bold text-zinc-400 text-lg">{Math.round(analysis.estimatedNutrition.carbs)}g</div>
                  </div>
                  <div className="bg-zinc-950 border border-zinc-800 p-3 rounded-xl text-center shadow-sm">
                    <div className="text-[9px] text-zinc-600 uppercase font-black">F</div>
                    <div className="font-bold text-zinc-400 text-lg">{Math.round(analysis.estimatedNutrition.fat)}g</div>
                  </div>
                </div>
              </div>

              <div className="space-y-3 px-1">
                <h4 className="font-black text-zinc-500 text-[10px] uppercase tracking-widest">Ingredients Detected</h4>
                <div className="flex flex-wrap gap-2">
                  {analysis.ingredientsFound.map((ing, i) => (
                    <span key={i} className="text-[11px] bg-zinc-900 text-zinc-400 px-3 py-1.5 rounded-xl font-bold border border-zinc-800">
                      {ing}
                    </span>
                  ))}
                </div>
              </div>

              <div className="flex gap-3 pt-4">
                <button 
                  onClick={() => setCapturedImage(null)}
                  className="flex-1 bg-zinc-900 text-zinc-600 font-bold py-4 rounded-2xl border border-zinc-800"
                >
                  Discard
                </button>
                <button 
                  onClick={handleConfirmSave}
                  className="flex-[2] bg-zinc-100 text-zinc-950 font-bold py-4 rounded-2xl shadow-xl shadow-white/5"
                >
                  Save to Wellness
                </button>
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export default MealLogger;

import React, { useState, useEffect } from 'react';
import { Meal, UserProfile, GroceryItem, Recipe } from './types';
import Dashboard from './components/Dashboard';
import MealLogger from './components/MealLogger';
import PantryView from './components/PantryView';
import ProfileSetup from './components/ProfileSetup';
import CookbookView from './components/CookbookView';
import Header from './components/Header';
import Footer from './components/Footer';

const App: React.FC = () => {
  const [view, setView] = useState<'dashboard' | 'logger' | 'pantry' | 'profile' | 'cookbook'>('pantry');
  const [meals, setMeals] = useState<Meal[]>([]);
  const [pantry, setPantry] = useState<GroceryItem[]>([]);
  const [savedRecipes, setSavedRecipes] = useState<Recipe[]>([]);
  const [profile, setProfile] = useState<UserProfile | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [deferredPrompt, setDeferredPrompt] = useState<any>(null);

  useEffect(() => {
    const savedMeals = localStorage.getItem('notripchef_meals');
    const savedProfile = localStorage.getItem('notripchef_profile');
    const savedPantry = localStorage.getItem('notripchef_pantry');
    const savedRecipesLocal = localStorage.getItem('notripchef_saved_recipes');

    if (savedMeals) setMeals(JSON.parse(savedMeals));
    if (savedPantry) setPantry(JSON.parse(savedPantry));
    if (savedProfile) setProfile(JSON.parse(savedProfile));
    if (savedRecipesLocal) setSavedRecipes(JSON.parse(savedRecipesLocal));

    window.addEventListener('beforeinstallprompt', (e) => {
      e.preventDefault();
      setDeferredPrompt(e);
    });
  }, []);

  useEffect(() => {
    localStorage.setItem('notripchef_meals', JSON.stringify(meals));
    localStorage.setItem('notripchef_pantry', JSON.stringify(pantry));
    localStorage.setItem('notripchef_saved_recipes', JSON.stringify(savedRecipes));
    if (profile) localStorage.setItem('notripchef_profile', JSON.stringify(profile));
  }, [meals, pantry, profile, savedRecipes]);

  const handleInstall = async () => {
    if (deferredPrompt) {
      deferredPrompt.prompt();
      const { outcome } = await deferredPrompt.userChoice;
      if (outcome === 'accepted') setDeferredPrompt(null);
    }
  };

  const handleAddMeal = (meal: Meal) => {
    setMeals(prev => [meal, ...prev]);
    setView('dashboard');
  };

  const handleSaveRecipe = (recipe: Recipe) => {
    if (!savedRecipes.find(r => r.title === recipe.title)) {
      setSavedRecipes(prev => [recipe, ...prev]);
    }
  };

  const handleDeleteRecipe = (title: string) => {
    setSavedRecipes(prev => prev.filter(r => r.title !== title));
  };

  return (
    <div className="min-h-screen flex flex-col max-w-md mx-auto bg-zinc-950 shadow-2xl relative overflow-hidden text-zinc-100">
      <Header setView={setView} currentView={view} />

      <main className="flex-1 overflow-y-auto pb-24 scroll-smooth">
        {view === 'pantry' && (
          <PantryView 
            items={pantry} 
            setItems={setPantry}
            onSaveRecipe={handleSaveRecipe}
            savedRecipes={savedRecipes}
          />
        )}

        {view === 'cookbook' && (
          <CookbookView 
            recipes={savedRecipes} 
            onDelete={handleDeleteRecipe} 
          />
        )}

        {view === 'dashboard' && profile && (
          <Dashboard 
            meals={meals} 
            profile={profile} 
            onDeleteMeal={(id) => setMeals(m => m.filter(x => x.id !== id))}
            onAddClick={() => setView('logger')}
          />
        )}

        {view === 'logger' && (
          <MealLogger 
            onSave={handleAddMeal} 
            onCancel={() => setView('dashboard')}
            isLoading={isLoading}
            setIsLoading={setIsLoading}
          />
        )}

        {view === 'profile' && (
          <ProfileSetup 
            profile={profile} 
            onSave={(p) => { setProfile(p); setView('pantry'); }} 
            onCancel={() => setView('pantry')}
            onInstall={deferredPrompt ? handleInstall : undefined}
          />
        )}
      </main>

      <Footer setView={setView} currentView={view} />
    </div>
  );
};

export default App;

