import React, { useState, useRef } from 'react';
import { GroceryItem, Recipe } from '../types';
import { analyzeGroceries, generateRecipeFromGroceries } from '../services/geminiService';

interface PantryViewProps {
  items: GroceryItem[];
  setItems: (items: GroceryItem[]) => void;
  onSaveRecipe: (recipe: Recipe) => void;
  savedRecipes: Recipe[];
}

const PantryView: React.FC<PantryViewProps> = ({ items, setItems, onSaveRecipe, savedRecipes }) => {
