              </div>
            </div>

            <div className="flex justify-between items-center mb-2 px-1">
              <label className="block text-[10px] font-black text-zinc-500 uppercase">Calorie Target</label>
              <button onClick={calculateSuggestedCalories} className="text-zinc-400 text-[10px] font-black uppercase tracking-wider hover:text-zinc-100">Auto-Tune</button>
            </div>
            <input 
              type="number" 
              name="dailyGoal" 
              value={formData.dailyGoal} 
              onChange={handleChange}
              className="w-full bg-zinc-900 border border-zinc-800 rounded-2xl px-5 py-5 text-zinc-100 font-black text-2xl"
            />
          </div>
        </div>

        <div className="flex gap-3 pt-6">
          {onCancel && (
            <button onClick={onCancel} className="flex-1 bg-zinc-900 text-zinc-600 font-bold py-4 rounded-2xl border border-zinc-800">Cancel</button>
          )}
          <button 
            onClick={() => onSave(formData)}
            className="flex-[2] bg-zinc-100 text-zinc-950 font-bold py-4 rounded-2xl shadow-xl shadow-white/5 active:scale-95 transition-all"
          >
            Confirm Changes
          </button>
        </div>
      </div>
    </div>
  );
};

