interface PantryViewProps {
  items: GroceryItem[];
  setItems: (items: GroceryItem[]) => void;
  onSaveRecipe: (recipe: Recipe) => void;
  savedRecipes: Recipe[];
  onInstall?: () => void;
}

const PantryView: React.FC<PantryViewProps> = ({ items, setItems, onSaveRecipe, savedRecipes, onInstall }) => {
  const [isScanning, setIsScanning] = useState(false);
  const [isGenerating, setIsGenerating] = useState(false);
  const [recipe, setRecipe] = useState<Recipe | null>(null);
  const [feedback, setFeedback] = useState<'up' | 'down' | null>(null);
  const [showInstallBanner, setShowInstallBanner] = useState(true);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const isSaved = recipe && savedRecipes.some(r => r.title === recipe.title);

  const handleScan = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setIsScanning(true);
    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64 = (reader.result as string).split(',')[1];
      try {
        const detected = await analyzeGroceries(base64);
        setItems([...detected, ...items]);
      } catch (err) {
        alert("Pantry scan failed. Please check your connection.");
      } finally {
        setIsScanning(false);
      }
    };
    reader.readAsDataURL(file);
  };

  const handleGetRecipe = async () => {
    if (items.length === 0) {
      alert("Scan some items in your fridge first!");
      return;
    }
    setIsGenerating(true);
    setFeedback(null); // Reset feedback for new recipe
    try {
      const result = await generateRecipeFromGroceries(items.map(i => i.name));
      setRecipe(result);
    } catch (err) {
      alert("Recipe generation failed. Try adding more items.");
    } finally {
      setIsGenerating(false);
    }
  };

  const handleFeedback = (type: 'up' | 'down') => {
    setFeedback(type);
    // In a real app, you'd send this to an analytics endpoint
    console.log(`Feedback received for ${recipe?.title}: ${type}`);
  };

  return (
    <div className="p-5 space-y-8 animate-in fade-in duration-500">
      {onInstall && showInstallBanner && (
        <div className="bg-zinc-100 rounded-3xl p-5 flex items-center justify-between shadow-2xl animate-pulse-soft">
          <div className="flex items-center gap-3">
            <div className="bg-zinc-950 text-white w-10 h-10 rounded-xl flex items-center justify-center">
              <i className="fas fa-download text-sm"></i>
            </div>
            <div>
              <h4 className="text-zinc-950 font-bold text-sm leading-tight">Download App</h4>
              <p className="text-zinc-500 text-[10px] uppercase font-black tracking-widest">Install for Offline Use</p>
            </div>
          </div>
          <div className="flex gap-2">
            <button 
              onClick={onInstall}
              className="bg-zinc-950 text-white text-[10px] font-black uppercase tracking-widest px-4 py-2 rounded-xl"
            >
              Install
            </button>
            <button onClick={() => setShowInstallBanner(false)} className="text-zinc-400 p-1">
              <i className="fas fa-times"></i>
            </button>
          </div>
        </div>
      )}

      <section className="space-y-2">
        <h2 className="text-3xl font-extrabold text-zinc-100 tracking-tight">Your Kitchen</h2>
        <p className="text-zinc-500 text-sm">Everything you need is already here.</p>
      </section>

      <div className="bg-zinc-900 rounded-[2.5rem] p-6 border border-zinc-800 shadow-sm relative overflow-hidden">
        <div className="flex justify-between items-center mb-6">
          <h3 className="font-bold text-zinc-400 uppercase tracking-widest text-[10px]">In-Stock Ingredients</h3>
          <span className="bg-zinc-800 text-zinc-300 text-[10px] font-bold px-3 py-1 rounded-full border border-zinc-700">{items.length} Items</span>
        </div>

