                </span>
                <span className="text-zinc-700">|</span>
                <span className="text-zinc-500 text-[10px] font-bold uppercase">{recipe.prepTime}</span>
              </div>
              <h3 className="text-2xl font-black text-zinc-100 leading-tight">{recipe.title}</h3>
            </div>
            <div className="flex gap-2">
              <button 
                onClick={() => onSaveRecipe(recipe)} 
                disabled={isSaved}
                className={`w-8 h-8 rounded-full flex items-center justify-center border ${isSaved ? 'bg-zinc-800 border-zinc-700 text-zinc-300' : 'bg-zinc-800 text-zinc-500 border-zinc-700 hover:text-zinc-100'}`}
              >
                <i className={`fas ${isSaved ? 'fa-check' : 'fa-bookmark'}`}></i>
