import { GoogleGenAI, Type } from "@google/genai";
import { FoodAnalysisResult, GroceryItem, Recipe } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });

export const analyzeMealImage = async (base64Image: string, userContext?: string): Promise<FoodAnalysisResult> => {
  const model = "gemini-3-flash-preview";
  const systemInstruction = `
    You are a professional Nutritionist with global expertise.
    Analyze the meal image and provide nutritional info. Expert in Global and Bangladeshi cuisines.
    Provide the response in structured JSON.
  `;
  const response = await ai.models.generateContent({
    model,
    contents: {
      parts: [
        { inlineData: { mimeType: "image/jpeg", data: base64Image } },
        { text: `Analyze this meal. ${userContext || ""}` }
      ]
    },
    config: {
      systemInstruction,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          foodName: { type: Type.STRING },
          confidence: { type: Type.NUMBER },
          estimatedNutrition: {
            type: Type.OBJECT,
            properties: {
              calories: { type: Type.NUMBER },
              protein: { type: Type.NUMBER },
              carbs: { type: Type.NUMBER },
              fat: { type: Type.NUMBER }
            },
            required: ["calories", "protein", "carbs", "fat"]
          },
          ingredientsFound: { type: Type.ARRAY, items: { type: Type.STRING } },
          suggestedPortion: { type: Type.STRING }
        },
        required: ["foodName", "estimatedNutrition", "ingredientsFound", "suggestedPortion"]
      }
    }
  });
  return JSON.parse(response.text || "{}");
};

export const analyzeGroceries = async (base64Image: string): Promise<GroceryItem[]> => {
  const model = "gemini-3-flash-preview";
  const systemInstruction = `
    Identify all raw grocery items and kitchen staples. 
    Be extremely precise with:
    1. Pantry Staples: Flour, sugar, salt, rice, various lentils (dal), oils, and vinegars.
    2. Spices: Turmeric, chili powder, cumin, coriander, cinnamon, cardamom, etc.
    3. Fresh Produce: Vegetables, fruits, and herbs.

    For each item, estimate the quantity or status (e.g., "500g bag", "Half full jar", "Small bunch", "1 liter bottle").
    Recognize items from both global markets and local Bangladeshi wet markets.
  `;
  const response = await ai.models.generateContent({
    model,
    contents: {
      parts: [
        { inlineData: { mimeType: "image/jpeg", data: base64Image } },
        { text: "List all identified grocery items with their estimated quantities." }
      ]
    },
    config: {
      systemInstruction,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            name: { type: Type.STRING },
            category: { type: Type.STRING, description: "e.g., Spice, Grain, Vegetable, Dairy" },
            quantity: { type: Type.STRING, description: "Estimated amount or package size" }
          },
          required: ["name", "category", "quantity"]
        }
      }
    }
  });
  const results = JSON.parse(response.text || "[]");
  return results.map((item: any) => ({ 
    ...item, 
    id: Math.random().toString(36).substr(2, 9) 
  }));
};

export const generateRecipeFromGroceries = async (pantryItems: string[]): Promise<Recipe> => {
  const model = "gemini-3-flash-preview";
  const systemInstruction = `
    You are a Master Chef with expertise in global and Bangladeshi cuisines, known for making complex cooking easy for absolute beginners. 
    Create a Halal-friendly recipe (strictly No Pork, No Alcohol).

    Instructional Style Guidelines:
    1. **Beginner-Friendly**: Use clear, simple language. Explain techniques briefly (e.g., "Dice the onion into small, 1/4 inch pieces").
    2. **Detailed Steps**: Break down complex actions into small, actionable sub-steps. Do not combine multiple different tasks in one instruction.
    3. **Precise Measurements**: Provide specific cooking temperatures (e.g., "medium-low heat", "hot but not smoking oil") and exact timings (e.g., "simmer for exactly 12-15 minutes").
    4. **Visual Cues**: Include visual indicators of doneness (e.g., "until the onions turn translucent and slightly golden at the edges").

    Ingredient Rules:
    - Use the provided ingredients found in the user's pantry. 
    - If essential ingredients for the recipe are missing, you MUST:
      1. List them in 'missingIngredientsDetails'.
      2. For each missing ingredient, provide a specific 'alternative' substitution that might already be in a typical kitchen (e.g., if 'Ghee' is missing, suggest 'Butter' or 'Oil').

    Ensure the recipe is flavorful, creative, and clearly explains how to use substitutions in the steps.
    Provide structured JSON output.
  `;

  const response = await ai.models.generateContent({
    model,
    contents: `The user has: ${pantryItems.join(", ")}. Suggest the best possible recipe following the detailed instructional style.`,
    config: {
      systemInstruction,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          title: { type: Type.STRING },
          description: { type: Type.STRING },
          prepTime: { type: Type.STRING },
          servings: { type: Type.NUMBER },
          ingredients: { type: Type.ARRAY, items: { type: Type.STRING } },
          instructions: { type: Type.ARRAY, items: { type: Type.STRING } },
          bangladeshiContext: { type: Type.STRING },
          missingIngredientsDetails: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                name: { 
                  type: Type.STRING, 
                  description: "The name of the missing ingredient." 
                },
                alternative: { 
                  type: Type.STRING, 
                  description: "A suitable substitute for the missing ingredient." 
                }
              },
              required: ["name", "alternative"]
            }
          }
        },
        required: ["title", "description", "prepTime", "ingredients", "instructions", "missingIngredientsDetails"]
      }
    }
  });

  return JSON.parse(response.text || "{}");
};

