const getCategoryIcon = (category: string) => {
  const cat = category.toLowerCase();
  if (cat.includes('vegetable')) return 'fa-carrot';
  if (cat.includes('fruit')) return 'fa-apple-whole';
  if (cat.includes('grain') || cat.includes('rice') || cat.includes('lentil') || cat.includes('dal')) return 'fa-wheat-awn';
  if (cat.includes('spice') || cat.includes('pantry staple')) return 'fa-pepper-hot';
  if (cat.includes('dairy') || cat.includes('milk')) return 'fa-cow';
  if (cat.includes('meat') || cat.includes('protein')) return 'fa-drumstick-bite';
  if (cat.includes('oil') || cat.includes('fat')) return 'fa-bottle-droplet';
  if (cat.includes('herb')) return 'fa-leaf';
  return 'fa-box-open';
};

