const CookbookView: React.FC<CookbookViewProps> = ({ recipes, onDelete }) => {
  const [selectedRecipe, setSelectedRecipe] = useState<Recipe | null>(null);
  const [copying, setCopying] = useState(false);

  const handleShare = async (recipe: Recipe) => {
    const shareData = {
      title: `Check out this recipe: ${recipe.title}`,
      text: `Hey! I found this awesome recipe: ${recipe.title}. ${recipe.description}`,
      url: window.location.href,
    };

    if (navigator.share) {
      try {
        await navigator.share(shareData);
      } catch (err) {
        console.error('Error sharing:', err);
      }
    } else {
      // Fallback: Copy to clipboard
      const shareText = `${shareData.title}\n\n${shareData.text}\n\nShared from NoTripChef`;
      try {
        await navigator.clipboard.writeText(shareText);
        setCopying(true);
        setTimeout(() => setCopying(false), 2000);
      } catch (err) {
        console.error('Clipboard error:', err);
        alert('Could not copy to clipboard.');
      }
    }
  };

  return (
    <div className="p-5 space-y-8 animate-in fade-in duration-500">
      <section className="space-y-2">
        <h2 className="text-3xl font-extrabold text-zinc-100 tracking-tight">Your Cookbook</h2>
        <p className="text-zinc-500 text-sm">Archived magic for your next session.</p>
      </section>

      {recipes.length === 0 ? (
        <div className="flex flex-col items-center justify-center py-20 text-center space-y-4">
          <div className="w-20 h-20 bg-zinc-900 rounded-full flex items-center justify-center border border-zinc-800 text-zinc-700">
            <i className="fas fa-book-sparkles text-3xl opacity-20"></i>
          </div>
          <p className="text-zinc-600 font-medium">No recipes saved yet.<br/>Generate some in the kitchen!</p>
        </div>
      ) : (
        <div className="grid gap-4">
          {recipes.map((recipe, idx) => (
            <div 
              key={idx}
              className="bg-zinc-900 border border-zinc-800 rounded-3xl p-5 flex items-center justify-between group cursor-pointer hover:border-zinc-600 transition-colors"
              onClick={() => setSelectedRecipe(recipe)}
            >
              <div className="flex-1 min-w-0 pr-4">
                <h3 className="font-bold text-zinc-100 truncate">{recipe.title}</h3>
                <p className="text-[10px] text-zinc-500 uppercase font-black tracking-widest mt-1">{recipe.prepTime} • {recipe.ingredients.length} Ingredients</p>
              </div>
              <div className="flex gap-2">
                 <button 
                  onClick={(e) => { e.stopPropagation(); onDelete(recipe.title); }}
                  className="w-8 h-8 rounded-full bg-zinc-950 border border-zinc-800 text-zinc-600 hover:text-rose-500 transition-colors flex items-center justify-center"
                >
                  <i className="fas fa-trash-can text-xs"></i>
                </button>
                <div className="w-8 h-8 rounded-full bg-zinc-100 text-zinc-950 flex items-center justify-center">
                  <i className="fas fa-chevron-right text-xs"></i>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}

      {selectedRecipe && (
        <div className="fixed inset-0 z-[60] bg-zinc-950/90 backdrop-blur-xl p-5 overflow-y-auto pb-24">
          <div className="max-w-md mx-auto space-y-8 py-10">
            <div className="flex justify-between items-start">
              <button 
                onClick={() => setSelectedRecipe(null)}
                className="bg-zinc-900 text-zinc-500 w-10 h-10 rounded-full flex items-center justify-center border border-zinc-800"
              >
                <i className="fas fa-arrow-left"></i>
              </button>
              <div className="flex gap-2">
                <button 
                  onClick={() => handleShare(selectedRecipe)}
                  className="bg-zinc-800 text-zinc-300 text-xs font-black uppercase tracking-widest px-4 py-2 rounded-xl border border-zinc-700 flex items-center gap-2 hover:bg-zinc-700 transition-all"
                >
                  <i className={`fas ${copying ? 'fa-check' : 'fa-share-nodes'}`}></i>
                  {copying ? 'Copied' : 'Share'}
                </button>
                <button 
                  onClick={() => { onDelete(selectedRecipe.title); setSelectedRecipe(null); }}
                  className="bg-rose-950/30 text-rose-500 text-xs font-black uppercase tracking-widest px-4 py-2 rounded-xl border border-rose-900/50"
                >
                  Remove
                </button>
              </div>
            </div>

            <div className="space-y-4">
              <div className="flex items-center gap-2">
                <span className="bg-zinc-800 text-zinc-300 text-[10px] font-black px-2 py-0.5 rounded-full uppercase tracking-widest border border-zinc-700">
                  SAVED RECIPE
                </span>
                <span className="text-zinc-500 text-[10px] font-bold uppercase">{selectedRecipe.prepTime}</span>
              </div>
              <h3 className="text-4xl font-black text-zinc-100 leading-tight">{selectedRecipe.title}</h3>
              <p className="text-zinc-500 italic leading-relaxed">"{selectedRecipe.description}"</p>
            </div>

            {selectedRecipe.missingIngredientsDetails && selectedRecipe.missingIngredientsDetails.length > 0 && (
              <div className="space-y-4">
                <h4 className="font-black text-rose-500 text-[10px] uppercase tracking-widest border-b border-rose-950/30 pb-2 flex items-center gap-2">
                  <i className="fas fa-triangle-exclamation"></i> Missing Items
                </h4>
                <div className="space-y-3">
                  {selectedRecipe.missingIngredientsDetails.map((missing, i) => (
                    <div key={i} className="bg-zinc-900 border border-zinc-800 p-3 rounded-2xl">
                      <div className="flex justify-between items-center mb-1">
                        <span className="text-sm font-bold text-zinc-200">{missing.name}</span>
                        <span className="text-[10px] text-zinc-500 font-black uppercase tracking-tighter">Use {missing.alternative} as substitute</span>
                      </div>
                      <OrderLinks ingredient={missing.name} />
                    </div>
                  ))}
                </div>
              </div>
            )}

            <div className="space-y-6">
              <div className="space-y-4">
                <h4 className="font-black text-zinc-100 text-xs uppercase tracking-widest border-b border-zinc-800 pb-2 flex items-center gap-2">
                  <i className="fas fa-list-ul"></i> Ingredients Needed
                </h4>
                <div className="grid gap-2">
                  {selectedRecipe.ingredients.map((ing, i) => (
                    <div key={i} className="flex items-center gap-3 text-sm text-zinc-400">
                      <div className="w-1.5 h-1.5 rounded-full bg-zinc-600"></div>
                      {ing}
                    </div>
                  ))}
                </div>
              </div>

              <div className="space-y-4">
                <h4 className="font-black text-zinc-100 text-xs uppercase tracking-widest border-b border-zinc-800 pb-2 flex items-center gap-2">
                  <i className="fas fa-fire-burner"></i> Cooking Steps
                </h4>
                <div className="space-y-6">
                  {selectedRecipe.instructions.map((step, i) => (
                    <div key={i} className="flex gap-4 items-start">
                      <div className="bg-zinc-100 text-zinc-950 w-6 h-6 rounded-lg flex items-center justify-center text-[10px] font-bold flex-shrink-0 mt-0.5">{i+1}</div>
                      <p className="text-sm text-zinc-400 leading-relaxed">{step}</p>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

