import { GoogleGenAI, Type } from "@google/genai";
import { FoodAnalysisResult, GroceryItem, Recipe } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });

export const analyzeMealImage = async (base64Image: string, userContext?: string): Promise<FoodAnalysisResult> => {
  const model = "gemini-3-flash-preview";
  const systemInstruction = `
    You are a professional Nutritionist with global expertise.
    Analyze the meal image and provide nutritional info. Expert in Global and Bangladeshi cuisines.
    Provide the response in structured JSON.
  `;
  const response = await ai.models.generateContent({
    model,
    contents: {
      parts: [
        { inlineData: { mimeType: "image/jpeg", data: base64Image } },
        { text: `Analyze this meal. ${userContext || ""}` }
      ]
    },
    config: {
      systemInstruction,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          foodName: { type: Type.STRING },
          confidence: { type: Type.NUMBER },
          estimatedNutrition: {
            type: Type.OBJECT,
            properties: {
              calories: { type: Type.NUMBER },
              protein: { type: Type.NUMBER },
              carbs: { type: Type.NUMBER },
              fat: { type: Type.NUMBER }
            },
            required: ["calories", "protein", "carbs", "fat"]
          },
          ingredientsFound: { type: Type.ARRAY, items: { type: Type.STRING } },
          suggestedPortion: { type: Type.STRING }
        },
        required: ["foodName", "estimatedNutrition", "ingredientsFound", "suggestedPortion"]
      }
    }
  });
  return JSON.parse(response.text || "{}");
};

export const analyzeGroceries = async (base64Image: string): Promise<GroceryItem[]> => {
  const model = "gemini-3-flash-preview";
  const systemInstruction = `
    Identify all raw grocery items and kitchen staples. 
    Be extremely precise with:
    1. Pantry Staples: Flour, sugar, salt, rice, various lentils (dal), oils, and vinegars.
    2. Spices: Turmeric, chili powder, cumin, coriander, cinnamon, cardamom, etc.
    3. Fresh Produce: Vegetables, fruits, and herbs.

    For each item, estimate the quantity or status (e.g., "500g bag", "Half full jar", "Small bunch", "1 liter bottle").
    Recognize items from both global markets and local Bangladeshi wet markets.
  `;
  const response = await ai.models.generateContent({
    model,
    contents: {
      parts: [
        { inlineData: { mimeType: "image/jpeg", data: base64Image } },
        { text: "List all identified grocery items with their estimated quantities." }
      ]
    },
    config: {
      systemInstruction,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            name: { type: Type.STRING },
            category: { type: Type.STRING, description: "e.g., Spice, Grain, Vegetable, Dairy" },
            quantity: { type: Type.STRING, description: "Estimated amount or package size" }
          },
          required: ["name", "category", "quantity"]
        }
      }
    }
  });
  const results = JSON.parse(response.text || "[]");
  return results.map((item: any) => ({ 
    ...item, 
    id: Math.random().toString(36).substr(2, 9) 
  }));
};

