              <p className="text-xs font-medium">Fridge is a blank canvas.<br/>Scan ingredients to start.</p>
            </div>
          ) : (
            <div className="grid grid-cols-1 gap-2">
              {items.map(item => (
                <div key={item.id} className="bg-white border border-slate-200 px-4 py-3 rounded-2xl shadow-sm flex items-center justify-between group hover:border-sage-400 transition-colors">
                  <div className="flex items-center gap-3 flex-1 min-w-0">
                    <span className="text-sm font-semibold text-slate-700 truncate">{item.name}</span>
                    <input 
                      type="text"
                      placeholder="e.g. 500g / 2 pcs"
                      value={item.quantity || ''}
                      onChange={(e) => handleQuantityChange(item.id, e.target.value)}
                      className="bg-slate-50 border-none text-[10px] font-bold px-2 py-1.5 rounded-lg focus:ring-1 focus:ring-sage-400 outline-none w-24 text-slate-600 placeholder:text-slate-300"
                    />
                  </div>
                  <button onClick={() => setItems(items.filter(i => i.id !== item.id))} className="text-slate-300 hover:text-rose-500 transition-colors ml-2">
                    <i className="fas fa-times-circle text-sm"></i>
                  </button>
