  };

  const handleShare = async () => {
    if (!recipe) return;
    const shareText = `🍳 ${recipe.title}\n"${recipe.description}"\n\n🛒 Ingredients:\n${recipe.ingredients.map(i => `- ${i}`).join('\n')}\n\n👨‍🍳 Instructions:\n${recipe.instructions.map((step, i) => `${i + 1}. ${step}`).join('\n')}\n\nShared via NoTripChef 🥗`.trim();
    if (navigator.share) {
      try { await navigator.share({ title: recipe.title, text: shareText }); } catch (err) { }
    } else {
      try { await navigator.clipboard.writeText(shareText); alert('Recipe copied to clipboard!'); } catch (err) { alert('Could not copy recipe.'); }
    }
  };

  return (
