        <div className="flex justify-between items-center mb-6">
          <h3 className="font-bold text-zinc-500 uppercase tracking-widest text-[10px]">In-Stock Ingredients</h3>
          <span className="bg-zinc-800 text-zinc-300 text-[10px] font-bold px-3 py-1 rounded-full border border-zinc-700">{items.length} Items</span>
        </div>

        <div className="flex flex-col gap-3 min-h-[120px]">
          {items.length === 0 ? (
            <div className="w-full flex flex-col items-center justify-center py-8 text-zinc-700 text-center">
              <i className="fas fa-kitchen-set text-4xl mb-3 opacity-20"></i>
              <p className="text-xs font-medium opacity-50">Fridge is empty.<br/>Scan ingredients to start.</p>
            </div>
          ) : (
            <div className="space-y-2">
              {items.map(item => (
                <div key={item.id} className="bg-zinc-950 border border-zinc-800 px-4 py-3 rounded-2xl shadow-sm flex items-center justify-between group hover:border-zinc-500 transition-colors">
                  <div className="flex items-center gap-3 flex-1 min-w-0">
                    <div className="bg-zinc-900 w-8 h-8 rounded-xl flex items-center justify-center text-zinc-500 flex-shrink-0">
                      <i className={`fas ${getCategoryIcon(item.category)} text-xs`}></i>
                    </div>
                    <span className="text-sm font-semibold text-zinc-300 truncate">{item.name}</span>
                    <input 
                      type="text"
                      placeholder="qty"
                      value={item.quantity || ''}
                      onChange={(e) => handleQuantityChange(item.id, e.target.value)}
                      className="bg-zinc-900 border-none text-[10px] font-bold px-2 py-1.5 rounded-lg focus:ring-1 focus:ring-zinc-600 outline-none w-20 text-zinc-400 placeholder:text-zinc-700"
                    />
