import { GoogleGenAI, Type } from "@google/genai";
import { FoodAnalysisResult, GroceryItem, Recipe } from "../types";

// Always use process.env.API_KEY directly when initializing
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const analyzeMealImage = async (base64Image: string, userContext?: string): Promise<FoodAnalysisResult> => {
  const model = "gemini-3-flash-preview";
  const systemInstruction = `
    You are a professional Nutritionist with global expertise.
    Analyze the meal image and provide nutritional info. Expert in Global and Bangladeshi cuisines.
    Provide the response in structured JSON.
  `;
  const response = await ai.models.generateContent({
    model,
    contents: {
      parts: [
        { inlineData: { mimeType: "image/jpeg", data: base64Image } },
        { text: `Analyze this meal. ${userContext || ""}` }
      ]
    },
    config: {
      systemInstruction,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          foodName: { type: Type.STRING },
          confidence: { type: Type.NUMBER },
          estimatedNutrition: {
            type: Type.OBJECT,
            properties: {
              calories: { type: Type.NUMBER },
              protein: { type: Type.NUMBER },
              carbs: { type: Type.NUMBER },
              fat: { type: Type.NUMBER }
            },
            required: ["calories", "protein", "carbs", "fat"]
          },
          ingredientsFound: { type: Type.ARRAY, items: { type: Type.STRING } },
          suggestedPortion: { type: Type.STRING }
        },
        required: ["foodName", "estimatedNutrition", "ingredientsFound", "suggestedPortion"]
      }
    }
  });
  return JSON.parse(response.text || "{}");
};

export const analyzeGroceries = async (base64Image: string): Promise<GroceryItem[]> => {
  const model = "gemini-3-flash-preview";
  const systemInstruction = "Identify all raw grocery items. Recognize items from global and local markets, especially Bangladeshi staples like different types of rice, lentils (dal), and regional vegetables.";
  const response = await ai.models.generateContent({
    model,
    contents: {
      parts: [
        { inlineData: { mimeType: "image/jpeg", data: base64Image } },
        { text: "List items found." }
      ]
    },
    config: {
      systemInstruction,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            name: { type: Type.STRING },
            category: { type: Type.STRING }
          },
          required: ["name", "category"]
        }
      }
    }
  });
  const results = JSON.parse(response.text || "[]");
  return results.map((item: any) => ({ ...item, id: Math.random().toString(36).substr(2, 9) }));
};

export const generateRecipeFromGroceries = async (pantryItems: string[]): Promise<Recipe> => {
  const model = "gemini-3-flash-preview";
  const systemInstruction = `
    You are a Master Chef expert in Halal-friendly Global and Bangladeshi cuisine. 
    Create a "Zero-Trip" recipe using the user's pantry.

    Substitution Intelligence:
    - If a core ingredient is missing, provide a diverse, descriptive alternative.
    - Match flavor profiles for spices (e.g., if Garam Masala is missing, suggest a blend of Cinnamon, Cardamom, and Cloves).
    - Suggest local alternatives (e.g., if Ghee is missing, explain using Mustard Oil for a pungent kick or Butter for richness).

    Local Relevance:
    - Heavily prioritize Bangladeshi staples (Rice, Dal, Bhorta styles) and cooking techniques.

    Output must be JSON.
  `;

  const response = await ai.models.generateContent({
    model,
    contents: `The user has: ${pantryItems.join(", ")}. Suggest the best recipe.`,
    config: {
      systemInstruction,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          title: { type: Type.STRING },
          description: { type: Type.STRING },
          prepTime: { type: Type.STRING },
          servings: { type: Type.NUMBER },
          ingredients: { type: Type.ARRAY, items: { type: Type.STRING } },
          instructions: { type: Type.ARRAY, items: { type: Type.STRING } },
          bangladeshiContext: { type: Type.STRING },
          missingIngredients: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                name: { type: Type.STRING },
                alternative: { type: Type.STRING, description: "A contextually relevant, descriptive substitution." }
              },
              required: ["name"]
            }
          }
        },
        required: ["title", "description", "prepTime", "ingredients", "instructions", "missingIngredients"]
      }
    }
  });

  return JSON.parse(response.text || "{}");
};

import React, { useState, useRef } from 'react';
import { GroceryItem, Recipe } from '../types';
import { analyzeGroceries, generateRecipeFromGroceries } from '../services/geminiService';

interface PantryViewProps {
  items: GroceryItem[];
  // Fix: use Dispatch/SetStateAction to correctly type state setters from useState
  setItems: React.Dispatch<React.SetStateAction<GroceryItem[]>>;
  savedRecipes: Recipe[];
  // Fix: use Dispatch/SetStateAction to correctly type state setters and resolve TS error on functional updates
  setSavedRecipes: React.Dispatch<React.SetStateAction<Recipe[]>>;
}

const PantryView: React.FC<PantryViewProps> = ({ items, setItems, savedRecipes, setSavedRecipes }) => {
  const [isScanning, setIsScanning] = useState(false);
  const [isGenerating, setIsGenerating] = useState(false);
  const [recipe, setRecipe] = useState<Recipe | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const getCategoryIcon = (category: string) => {
    const cat = category.toLowerCase();
    if (cat.includes('veg')) return 'fa-carrot';
    if (cat.includes('fruit')) return 'fa-apple-whole';
    if (cat.includes('meat') || cat.includes('protein') || cat.includes('chicken') || cat.includes('beef')) return 'fa-drumstick-bite';
    if (cat.includes('fish') || cat.includes('seafood')) return 'fa-fish';
    if (cat.includes('grain') || cat.includes('rice') || cat.includes('wheat')) return 'fa-wheat-awn';
    if (cat.includes('spice') || cat.includes('seasoning') || cat.includes('masala')) return 'fa-pepper-hot';
    if (cat.includes('dairy') || cat.includes('milk') || cat.includes('cheese')) return 'fa-cheese';
    if (cat.includes('oil') || cat.includes('ghee')) return 'fa-bottle-droplet';
    if (cat.includes('pulse') || cat.includes('dal') || cat.includes('lentil')) return 'fa-seedling';
    return 'fa-box-archive';
  };

  const handleScan = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setIsScanning(true);
    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64 = (reader.result as string).split(',')[1];
      try {
        const detected = await analyzeGroceries(base64);
        // Use functional update for better reliability
        setItems(prev => [...detected, ...prev]);
      } catch (err) {
        alert("Pantry scan failed. Please check your connection.");
      } finally {
        setIsScanning(false);
      }
    };
    reader.readAsDataURL(file);
  };

  const handleQuantityChange = (id: string, value: string) => {
    setItems(items.map(item => item.id === id ? { ...item, quantity: value } : item));
  };

  const handleGetRecipe = async () => {
    if (items.length === 0) {
      alert("Scan some items in your fridge first!");
      return;
    }
    setIsGenerating(true);
    setRecipe(null);
    try {
      const pantryStrings = items.map(i => i.quantity ? `${i.quantity} ${i.name}` : i.name);
      const result = await generateRecipeFromGroceries(pantryStrings);
      setRecipe({ ...result, id: Date.now().toString() });
    } catch (err) {
      alert("Recipe generation failed. Try adding more items.");
    } finally {
      setIsGenerating(false);
    }
  };

  const handleRating = (rating: 'up' | 'down') => {
    if (!recipe) return;

    const newRating = recipe.userRating === rating ? null : rating;
    const updatedRecipe = { ...recipe, userRating: newRating };
    setRecipe(updatedRecipe);

    if (newRating) {
      // Save or update in saved recipes list
      setSavedRecipes(prev => {
        const existingIndex = prev.findIndex(r => r.title === updatedRecipe.title);
        if (existingIndex > -1) {
          const newSaved = [...prev];
          newSaved[existingIndex] = updatedRecipe;
          return newSaved;
        }
        return [updatedRecipe, ...prev];
      });
    }
  };

  const openOrderLink = (platform: 'chaldal' | 'pathao' | 'pandamart', item: string) => {
    let url = '';
    const query = encodeURIComponent(item);
    switch (platform) {
      case 'chaldal':
        url = `https://chaldal.com/search/${query}`;
        break;
      case 'pathao':
        url = `https://pathao.com/food/`;
        break;
      case 'pandamart':
        url = `https://www.foodpanda.com.bd/darkstore/search?q=${query}`;
        break;
    }
    window.open(url, '_blank');
  };

  const handleShare = async () => {
    if (!recipe) return;
    const shareText = `🍳 ${recipe.title}\n"${recipe.description}"\n\n🛒 Ingredients:\n${recipe.ingredients.map(i => `- ${i}`).join('\n')}\n\n👨‍🍳 Instructions:\n${recipe.instructions.map((step, i) => `${i + 1}. ${step}`).join('\n')}\n\nShared via NoTripChef 🥗`.trim();
    if (navigator.share) {
      try { await navigator.share({ title: recipe.title, text: shareText }); } catch (err) { }
    } else {
      try { await navigator.clipboard.writeText(shareText); alert('Recipe copied to clipboard!'); } catch (err) { alert('Could not copy recipe.'); }
    }
  };

  const handleDeleteSaved = (id: string | undefined) => {
    if (!id) return;
    setSavedRecipes(prev => prev.filter(r => r.id !== id));
  };

  return (
    <div className="p-5 space-y-8 animate-in fade-in duration-500 pb-20">
      <section className="space-y-2">
        <h2 className="text-3xl font-extrabold text-zinc-100 tracking-tight">Your Kitchen</h2>
        <p className="text-zinc-500 text-sm">Magic happens with what's already here.</p>
      </section>

      <div className="bg-zinc-900 rounded-[2.5rem] p-6 border border-zinc-800 shadow-sm relative overflow-hidden">
        <div className="flex justify-between items-center mb-6">
          <h3 className="font-bold text-zinc-500 uppercase tracking-widest text-[10px]">In-Stock Ingredients</h3>
          <span className="bg-zinc-800 text-zinc-300 text-[10px] font-bold px-3 py-1 rounded-full border border-zinc-700">{items.length} Items</span>
        </div>

        <div className="flex flex-col gap-3 min-h-[120px]">
          {items.length === 0 ? (
            <div className="w-full flex flex-col items-center justify-center py-8 text-zinc-700 text-center">
              <i className="fas fa-kitchen-set text-4xl mb-3 opacity-20"></i>
              <p className="text-xs font-medium opacity-50">Fridge is empty.<br/>Scan ingredients to start.</p>
            </div>
          ) : (
            <div className="space-y-2">
              {items.map(item => (
                <div key={item.id} className="bg-zinc-950 border border-zinc-800 px-4 py-3 rounded-2xl shadow-sm flex items-center justify-between group hover:border-zinc-500 transition-colors">
                  <div className="flex items-center gap-3 flex-1 min-w-0">
                    <div className="bg-zinc-900 w-8 h-8 rounded-xl flex items-center justify-center text-zinc-500 flex-shrink-0">
                      <i className={`fas ${getCategoryIcon(item.category)} text-xs`}></i>
                    </div>
                    <span className="text-sm font-semibold text-zinc-300 truncate">{item.name}</span>
                    <input 
                      type="text"
                      placeholder="qty"
                      value={item.quantity || ''}
                      onChange={(e) => handleQuantityChange(item.id, e.target.value)}
                      className="bg-zinc-900 border-none text-[10px] font-bold px-2 py-1.5 rounded-lg focus:ring-1 focus:ring-zinc-600 outline-none w-20 text-zinc-400 placeholder:text-zinc-700"
                    />
                  </div>
                  <button onClick={() => setItems(prev => prev.filter(i => i.id !== item.id))} className="text-zinc-700 hover:text-rose-500 transition-colors ml-2">
                    <i className="fas fa-times-circle text-sm"></i>
                  </button>
                </div>
              ))}
            </div>
          )}
        </div>

        <button 
          onClick={() => fileInputRef.current?.click()}
          className="mt-6 w-full bg-zinc-950 border-2 border-dashed border-zinc-800 text-zinc-500 py-3 rounded-2xl font-bold text-sm flex items-center justify-center gap-2 hover:bg-zinc-900 hover:text-zinc-300 transition-all"
        >
          <i className={`fas ${isScanning ? 'fa-spinner fa-spin' : 'fa-camera'}`}></i>
          {isScanning ? 'Identifying...' : 'Add Ingredients'}
        </button>
        <input type="file" className="hidden" ref={fileInputRef} onChange={handleScan} accept="image/*" />
      </div>

      <button 
        onClick={handleGetRecipe}
        disabled={isGenerating || items.length === 0}
        className="w-full bg-zinc-100 text-zinc-950 font-black py-5 rounded-[2rem] shadow-xl shadow-white/5 flex items-center justify-center gap-3 active:scale-95 transition-all disabled:opacity-30"
      >
        {isGenerating ? (
          <><i className="fas fa-hat-chef fa-spin"></i> Finding a Recipe...</>
        ) : (
          <><i className="fas fa-wand-magic-sparkles"></i> Generate No-Trip Recipe</>
        )}
      </button>

      {recipe && (
        <div className="bg-zinc-900 rounded-[2.5rem] border border-zinc-800 shadow-2xl p-7 space-y-6 animate-in slide-in-from-bottom-10 duration-700">
          <div className="flex justify-between items-start">
            <div className="flex-1 pr-4">
              <div className="flex items-center gap-2 mb-2">
                <span className="bg-emerald-950/30 text-emerald-400 text-[9px] font-black px-2 py-0.5 rounded-full uppercase tracking-widest border border-emerald-900/50">
                  {recipe.missingIngredients.length === 0 ? 'TRIP NOT NEEDED' : 'NEARLY READY'}
                </span>
                <span className="text-zinc-700">|</span>
                <span className="text-zinc-500 text-[10px] font-bold uppercase">{recipe.prepTime}</span>
              </div>
              <h3 className="text-2xl font-black text-zinc-100 leading-tight">{recipe.title}</h3>
            </div>
            <div className="flex items-center gap-2">
              <button onClick={handleShare} className="bg-zinc-800 text-zinc-500 w-8 h-8 rounded-full flex items-center justify-center border border-zinc-700 hover:text-zinc-100 transition-all"><i className="fas fa-share-nodes text-xs"></i></button>
              <button onClick={() => setRecipe(null)} className="bg-zinc-800 text-zinc-500 w-8 h-8 rounded-full flex items-center justify-center border border-zinc-700 hover:text-rose-500 transition-all"><i className="fas fa-times"></i></button>
            </div>
          </div>

          <p className="text-zinc-500 text-sm italic leading-relaxed">"{recipe.description}"</p>

          {recipe.missingIngredients.length > 0 && (
            <div className="bg-amber-950/10 rounded-3xl p-5 border border-amber-900/30 space-y-3">
              <h4 className="text-[10px] font-black text-amber-600 uppercase tracking-widest flex items-center gap-2">
                <i className="fas fa-route"></i> Smart Substitutions
              </h4>
              <div className="flex flex-col gap-3">
                {recipe.missingIngredients.map((missing, i) => (
                  <div key={i} className="bg-zinc-950 p-3 rounded-xl border border-amber-900/20 shadow-sm space-y-2">
                    <div className="text-xs font-black text-zinc-200 uppercase">{missing.name}</div>
                    {missing.alternative && (
                      <p className="text-[10px] text-emerald-400 font-medium leading-tight">
                        <span className="text-amber-600 font-bold">Pro Tip:</span> {missing.alternative}
                      </p>
                    )}
                    <div className="flex flex-wrap gap-1.5 pt-1">
                      <button onClick={() => openOrderLink('chaldal', missing.name)} className="text-[8px] font-bold bg-[#ffeb3b] text-slate-900 px-2 py-1 rounded-md border border-yellow-400">Chaldal</button>
                      <button onClick={() => openOrderLink('pandamart', missing.name)} className="text-[8px] font-bold bg-[#D70F64] text-white px-2 py-1 rounded-md">Panda Mart</button>
                      <button onClick={() => openOrderLink('pathao', missing.name)} className="text-[8px] font-bold bg-white text-zinc-900 px-2 py-1 rounded-md">Pathao</button>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}

          <div className="space-y-4">
            <h4 className="font-black text-zinc-500 text-xs uppercase tracking-widest border-b border-zinc-800 pb-2">Chef's Steps</h4>
            <div className="space-y-6">
              {recipe.instructions.map((step, i) => (
                <div key={i} className="flex gap-4 items-start">
                  <div className="bg-zinc-100 text-zinc-950 w-6 h-6 rounded-lg flex items-center justify-center text-[10px] font-bold flex-shrink-0 mt-0.5">{i+1}</div>
                  <p className="text-sm text-zinc-400 leading-relaxed">{step}</p>
                </div>
              ))}
            </div>
          </div>

          <div className="pt-6 border-t border-zinc-800 flex flex-col items-center gap-4">
            <p className="text-[10px] font-black text-zinc-500 uppercase tracking-widest">Recipe Feedback</p>
            <div className="flex gap-4">
              <button onClick={() => handleRating('up')} className={`w-14 h-14 rounded-2xl flex items-center justify-center transition-all ${recipe.userRating === 'up' ? 'bg-emerald-600 text-white shadow-lg shadow-emerald-900/20' : 'bg-zinc-800 text-zinc-600'}`}>
                <i className="fas fa-thumbs-up text-lg"></i>
              </button>
              <button onClick={() => handleRating('down')} className={`w-14 h-14 rounded-2xl flex items-center justify-center transition-all ${recipe.userRating === 'down' ? 'bg-rose-600 text-white shadow-lg shadow-rose-900/20' : 'bg-zinc-800 text-zinc-600'}`}>
                <i className="fas fa-thumbs-down text-lg"></i>
              </button>
            </div>
            {recipe.userRating && <p className="text-[10px] font-bold text-emerald-500">Feedback Saved to History!</p>}
          </div>
        </div>
      )}

      {/* Recipe History Section */}
      {savedRecipes.length > 0 && (
        <section className="space-y-4 pt-4 border-t border-zinc-900">
          <div className="flex justify-between items-center px-1">
            <h4 className="text-[10px] font-black text-zinc-500 uppercase tracking-widest">Recipe History</h4>
            <span className="text-[10px] text-zinc-700 font-bold">{savedRecipes.length} Saved</span>
          </div>
          <div className="grid grid-cols-1 gap-3">
            {savedRecipes.map(r => (
              <div key={r.id} className="bg-zinc-900/50 p-4 rounded-3xl border border-zinc-800 flex items-center justify-between group">
                <div className="flex-1 min-w-0 cursor-pointer" onClick={() => setRecipe(r)}>
                  <h5 className="font-bold text-zinc-300 truncate text-sm">{r.title}</h5>
                  <div className="flex items-center gap-2 mt-1">
                    <span className="text-[9px] text-zinc-600 font-black uppercase tracking-tighter">{r.prepTime}</span>
                    <span className="text-zinc-800 text-[10px]">•</span>
                    <span className={`text-[10px] ${r.userRating === 'up' ? 'text-emerald-600' : 'text-rose-600'}`}>
                      <i className={`fas ${r.userRating === 'up' ? 'fa-thumbs-up' : 'fa-thumbs-down'} text-[10px]`}></i>
                    </span>
                  </div>
                </div>
                <button 
                  onClick={() => handleDeleteSaved(r.id)} 
                  className="w-8 h-8 rounded-full flex items-center justify-center text-zinc-700 hover:text-rose-500 transition-colors"
                >
                  <i className="fas fa-trash-can text-xs"></i>
                </button>
              </div>
            ))}
          </div>
        </section>
      )}
    </div>
  );
};

