              href="https://play.google.com" 
              target="_blank" 
              rel="noopener noreferrer"
              className="bg-zinc-900 border border-zinc-800 rounded-2xl p-3 flex items-center gap-2 hover:bg-zinc-800 transition-colors group"
            >
              <i className="fab fa-google-play text-lg text-zinc-100"></i>
              <div className="text-left">
                <p className="text-[7px] text-zinc-500 font-bold uppercase leading-none">Get it on</p>
                <p className="text-[10px] font-bold text-zinc-100 leading-tight">Google Play</p>
              </div>
            </a>
          </div>
        </div>
      </section>

      <div className="space-y-6">
        <div className="space-y-4">
          <div>
            <label className="block text-[10px] font-black text-zinc-500 uppercase mb-2 ml-1 tracking-widest">Chef Handle</label>
            <input 
              type="text" 
              name="name" 
              value={formData.name} 
              onChange={handleChange}
              placeholder="Your Name"
              className="w-full bg-zinc-900 border border-zinc-800 rounded-2xl px-5 py-4 focus:ring-1 focus:ring-zinc-500 focus:outline-none font-semibold text-zinc-100 placeholder-zinc-700"
            />
          </div>

          <div className="pt-6 border-t border-zinc-800">
            <h4 className="text-[10px] font-black text-zinc-500 uppercase mb-4 ml-1 tracking-widest">Body Metrics</h4>
            <div className="grid grid-cols-2 gap-4 mb-4">
              <div>
                <label className="block text-[10px] font-bold text-zinc-600 uppercase mb-2 ml-1">Weight (kg)</label>
                <input type="number" name="weight" value={formData.weight} onChange={handleChange} className="w-full bg-zinc-900 border border-zinc-800 rounded-2xl px-4 py-3 text-zinc-100" />
              </div>
              <div>
                <label className="block text-[10px] font-bold text-zinc-600 uppercase mb-2 ml-1">Height (cm)</label>
                <input type="number" name="height" value={formData.height} onChange={handleChange} className="w-full bg-zinc-900 border border-zinc-800 rounded-2xl px-4 py-3 text-zinc-100" />
              </div>
            </div>

            <div className="flex justify-between items-center mb-2 px-1">
              <label className="block text-[10px] font-black text-zinc-500 uppercase">Calorie Target</label>
              <button onClick={calculateSuggestedCalories} className="text-zinc-400 text-[10px] font-black uppercase tracking-wider hover:text-zinc-100">Auto-Tune</button>
            </div>
            <input 
              type="number" 
              name="dailyGoal" 
              value={formData.dailyGoal} 
              onChange={handleChange}
              className="w-full bg-zinc-900 border border-zinc-800 rounded-2xl px-5 py-5 text-zinc-100 font-black text-2xl"
            />
          </div>
        </div>

        <div className="flex gap-3 pt-6">
          {onCancel && (
            <button onClick={onCancel} className="flex-1 bg-zinc-900 text-zinc-600 font-bold py-4 rounded-2xl border border-zinc-800">Cancel</button>
          )}
          <button 
            onClick={() => onSave(formData)}
            className="flex-[2] bg-zinc-100 text-zinc-950 font-bold py-4 rounded-2xl shadow-xl shadow-white/5 active:scale-95 transition-all"
          >
            Confirm Changes
          </button>
        </div>
      </div>
    </div>
  );
};

export default ProfileSetup;

import React, { useState, useEffect } from 'react';
import { Meal, UserProfile, GroceryItem, Recipe } from './types';
import Dashboard from './components/Dashboard';
import MealLogger from './components/MealLogger';
import PantryView from './components/PantryView';
import ProfileSetup from './components/ProfileSetup';
import CookbookView from './components/CookbookView';
import Header from './components/Header';
import Footer from './components/Footer';

const App: React.FC = () => {
  const [view, setView] = useState<'dashboard' | 'logger' | 'pantry' | 'profile' | 'cookbook'>('pantry');
  const [meals, setMeals] = useState<Meal[]>([]);
  const [pantry, setPantry] = useState<GroceryItem[]>([]);
  const [savedRecipes, setSavedRecipes] = useState<Recipe[]>([]);
  const [profile, setProfile] = useState<UserProfile | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [deferredPrompt, setDeferredPrompt] = useState<any>(null);

  useEffect(() => {
    const savedMeals = localStorage.getItem('notripchef_meals');
    const savedProfile = localStorage.getItem('notripchef_profile');
    const savedPantry = localStorage.getItem('notripchef_pantry');
    const savedRecs = localStorage.getItem('notripchef_saved_recipes');

    if (savedMeals) setMeals(JSON.parse(savedMeals));
    if (savedPantry) setPantry(JSON.parse(savedPantry));
    if (savedProfile) setProfile(JSON.parse(savedProfile));
    if (savedRecs) setSavedRecipes(JSON.parse(savedRecs));

    window.addEventListener('beforeinstallprompt', (e) => {
      e.preventDefault();
      setDeferredPrompt(e);
    });
  }, []);

  useEffect(() => {
    localStorage.setItem('notripchef_meals', JSON.stringify(meals));
    localStorage.setItem('notripchef_pantry', JSON.stringify(pantry));
    localStorage.setItem('notripchef_saved_recipes', JSON.stringify(savedRecipes));
    if (profile) localStorage.setItem('notripchef_profile', JSON.stringify(profile));
  }, [meals, pantry, profile, savedRecipes]);

  const handleInstall = async () => {
    if (deferredPrompt) {
      deferredPrompt.prompt();
      const { outcome } = await deferredPrompt.userChoice;
      if (outcome === 'accepted') setDeferredPrompt(null);
    }
  };

  const handleAddMeal = (meal: Meal) => {
    setMeals(prev => [meal, ...prev]);
    setView('dashboard');
  };

  return (
    <div className="min-h-screen flex flex-col max-w-md mx-auto bg-zinc-950 shadow-2xl relative overflow-hidden text-zinc-100">
      <Header setView={setView} currentView={view} />

      <main className="flex-1 overflow-y-auto pb-24 scroll-smooth">
        {view === 'pantry' && (
          <PantryView 
            items={pantry} 
            setItems={setPantry}
            savedRecipes={savedRecipes}
            setSavedRecipes={setSavedRecipes}
            onViewCookbook={() => setView('cookbook')}
          />
        )}

        {view === 'cookbook' && (
          <CookbookView 
            recipes={savedRecipes}
            setSavedRecipes={setSavedRecipes}
            onBack={() => setView('pantry')}
          />
        )}

        {view === 'dashboard' && profile && (
          <Dashboard 
            meals={meals} 
            profile={profile} 
            onDeleteMeal={(id) => setMeals(m => m.filter(x => x.id !== id))}
            onAddClick={() => setView('logger')}
          />
        )}

        {view === 'logger' && (
          <MealLogger 
            onSave={handleAddMeal} 
            onCancel={() => setView('dashboard')}
            isLoading={isLoading}
            setIsLoading={setIsLoading}
          />
        )}

        {view === 'profile' && (
          <ProfileSetup 
            profile={profile} 
            onSave={(p) => { setProfile(p); setView('pantry'); }} 
            onCancel={() => setView('pantry')}
            onInstall={deferredPrompt ? handleInstall : undefined}
          />
        )}
      </main>

      <Footer setView={setView} currentView={view} />
    </div>
  );
};

export default App;

