              >
                <i className="fas fa-thumbs-up text-lg"></i>
              </button>
              <button 
                onClick={() => handleRating('down')} 
                className={`w-14 h-14 rounded-2xl flex items-center justify-center transition-all ${recipe.userRating === 'down' ? 'bg-rose-600 text-white shadow-lg shadow-rose-900/20' : 'bg-zinc-800 text-zinc-600'}`}
