                  onChange={(e) => setFeedbackText(e.target.value)}
                  placeholder="What was wrong? (e.g., ingredients don't match, too complex...)"
                  className="w-full bg-zinc-950 border border-zinc-800 rounded-xl p-3 text-xs text-zinc-300 placeholder:text-zinc-700 focus:ring-1 focus:ring-zinc-600 outline-none min-h-[80px] resize-none"
                />
                <button 
                  onClick={() => handleGetRecipe(feedbackText)}
                  disabled={isGenerating || !feedbackText.trim()}
                  className="w-full bg-zinc-800 text-zinc-100 font-bold py-3 rounded-xl text-[10px] uppercase tracking-widest hover:bg-zinc-700 disabled:opacity-30 transition-all flex items-center justify-center gap-2"
                >
                  <i className="fas fa-rotate-right"></i>
                  Refine Recipe with Feedback
                </button>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

