import React, { useState, useEffect } from 'react';
import { UserProfile, GroceryItem, DietPlan } from '../types';
import { generateDailyDietPlan } from '../services/geminiService';

interface DietPlanViewProps {
  profile: UserProfile | null;
  pantry: GroceryItem[];
  onBack: () => void;
}

const DietPlanView: React.FC<DietPlanViewProps> = ({ profile, pantry, onBack }) => {
  const [dietPlan, setDietPlan] = useState<DietPlan | null>(null);
  const [isLoading, setIsLoading] = useState(false);

  useEffect(() => {
    const savedPlan = localStorage.getItem('notripchef_daily_diet');
    if (savedPlan) {
      const parsed = JSON.parse(savedPlan);
      // Only keep the plan if it's for today
      const today = new Date().toISOString().split('T')[0];
      if (parsed.date === today) {
        setDietPlan(parsed);
      }
    }
  }, []);

  const handleGenerate = async () => {
    if (!profile) {
      alert("Please complete your profile setup first!");
      return;
    }
    setIsLoading(true);
    try {
      const pantryStrings = pantry.map(i => i.quantity ? `${i.quantity} ${i.name}` : i.name);
      const plan = await generateDailyDietPlan(profile, pantryStrings);
      const today = new Date().toISOString().split('T')[0];
      const planWithDate = { ...plan, date: today };
      setDietPlan(planWithDate);
      localStorage.setItem('notripchef_daily_diet', JSON.stringify(planWithDate));
    } catch (err) {
      console.error(err);
      alert("Failed to generate diet plan. Please try again.");
    } finally {
      setIsLoading(false);
    }
  };

  if (!profile) {
    return (
      <div className="p-8 text-center space-y-6">
        <div className="w-20 h-20 bg-zinc-900 rounded-full flex items-center justify-center mx-auto text-zinc-700 border border-zinc-800">
          <i className="fas fa-user-lock text-3xl"></i>
        </div>
        <div className="space-y-2">
          <h2 className="text-xl font-black text-zinc-100 uppercase tracking-tighter">Profile Locked</h2>
          <p className="text-sm text-zinc-500">We need your age, weight, and goals to build a custom diet plan.</p>
        </div>
        <button 
          onClick={onBack}
          className="bg-zinc-100 text-zinc-950 font-black px-8 py-4 rounded-2xl shadow-xl uppercase text-xs tracking-widest"
        >
          Setup Profile
        </button>
      </div>
    );
  }

  return (
    <div className="p-5 space-y-8 pb-32 animate-in fade-in duration-500">
      <header className="flex justify-between items-end">
        <div>
          <h2 className="text-3xl font-black text-zinc-100 tracking-tight">Diet Plan</h2>
          <p className="text-zinc-500 text-sm">AI-Optimized for {profile.name}.</p>
        </div>
        <button 
          onClick={handleGenerate}
          disabled={isLoading}
          className="text-[9px] font-black uppercase bg-zinc-800 text-zinc-400 px-3 py-1.5 rounded-full border border-zinc-700 hover:text-white transition-colors disabled:opacity-50"
        >
          {isLoading ? <i className="fas fa-spinner fa-spin mr-1"></i> : <i className="fas fa-rotate mr-1"></i>}
          Refresh Plan
        </button>
      </header>

      {!dietPlan && !isLoading ? (
        <div className="bg-zinc-900/50 border border-zinc-800 rounded-[2.5rem] p-10 text-center space-y-6">
          <div className="w-24 h-24 bg-zinc-950 rounded-[2rem] flex items-center justify-center mx-auto text-zinc-800 border border-zinc-800 shadow-inner">
            <i className="fas fa-plate-wheat text-4xl opacity-30"></i>
          </div>
          <div className="space-y-2">
