import React, { useState, useEffect } from 'react';
import { Meal, UserProfile, GroceryItem, Recipe } from './types';
import Dashboard from './components/Dashboard';
import MealLogger from './components/MealLogger';
import PantryView from './components/PantryView';
import ProfileSetup from './components/ProfileSetup';
import CookbookView from './components/CookbookView';
import DietPlanView from './components/DietPlanView';
import InstructionsView from './components/InstructionsView';
import Header from './components/Header';
import Footer from './components/Footer';

const App: React.FC = () => {
  const [view, setView] = useState<'dashboard' | 'logger' | 'pantry' | 'profile' | 'cookbook' | 'dietPlan' | 'instructions'>('pantry');
  const [meals, setMeals] = useState<Meal[]>([]);
  const [pantry, setPantry] = useState<GroceryItem[]>([]);
  const [savedRecipes, setSavedRecipes] = useState<Recipe[]>([]);
  const [profile, setProfile] = useState<UserProfile | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [deferredPrompt, setDeferredPrompt] = useState<any>(null);

  useEffect(() => {
    const savedMeals = localStorage.getItem('notripchef_meals');
    const savedProfile = localStorage.getItem('notripchef_profile');
    const savedPantry = localStorage.getItem('notripchef_pantry');
    const savedRecs = localStorage.getItem('notripchef_saved_recipes');

    if (savedMeals) setMeals(JSON.parse(savedMeals));
    if (savedPantry) setPantry(JSON.parse(savedPantry));
    if (savedProfile) setProfile(JSON.parse(savedProfile));
    if (savedRecs) setSavedRecipes(JSON.parse(savedRecs));

    window.addEventListener('beforeinstallprompt', (e) => {
      e.preventDefault();
      setDeferredPrompt(e);
    });
  }, []);

  useEffect(() => {
    localStorage.setItem('notripchef_meals', JSON.stringify(meals));
    localStorage.setItem('notripchef_pantry', JSON.stringify(pantry));
    localStorage.setItem('notripchef_saved_recipes', JSON.stringify(savedRecipes));
    if (profile) localStorage.setItem('notripchef_profile', JSON.stringify(profile));
  }, [meals, pantry, profile, savedRecipes]);

  const handleInstall = async () => {
    if (deferredPrompt) {
      deferredPrompt.prompt();
      const { outcome } = await deferredPrompt.userChoice;
      if (outcome === 'accepted') setDeferredPrompt(null);
    }
  };

  const handleAddMeal = (meal: Meal) => {
    setMeals(prev => [meal, ...prev]);
    setView('dashboard');
  };

  return (
    <div className="min-h-screen flex flex-col max-w-md mx-auto bg-zinc-950 shadow-2xl relative overflow-hidden text-zinc-100">
      <Header setView={setView as any} currentView={view} />

      <main className="flex-1 overflow-y-auto pb-24 scroll-smooth">
        {view === 'pantry' && (
          <PantryView 
            items={pantry} 
            setItems={setPantry}
            savedRecipes={savedRecipes}
            setSavedRecipes={setSavedRecipes}
            onViewCookbook={() => setView('cookbook')}
          />
        )}

        {view === 'cookbook' && (
          <CookbookView 
            recipes={savedRecipes}
            setSavedRecipes={setSavedRecipes}
            onBack={() => setView('pantry')}
            viewTitle="Cookbook"
            emptyMessage="Your cookbook is empty. Generate a recipe in the kitchen and save it to see it here."
          />
        )}

        {view === 'dietPlan' && (
          <DietPlanView 
            profile={profile}
            pantry={pantry}
            onBack={() => setView('profile')}
          />
        )}

        {view === 'dashboard' && profile && (
          <Dashboard 
            meals={meals} 
            profile={profile} 
            onDeleteMeal={(id) => setMeals(m => m.filter(x => x.id !== id))}
            onAddClick={() => setView('logger')}
          />
        )}

        {view === 'logger' && (
          <MealLogger 
            onSave={handleAddMeal} 
            onCancel={() => setView('dashboard')}
            isLoading={isLoading}
            setIsLoading={setIsLoading}
          />
        )}

        {view === 'profile' && (
          <ProfileSetup 
            profile={profile} 
            onSave={(p) => { setProfile(p); setView('pantry'); }} 
            onCancel={() => setView('pantry')}
            onInstall={deferredPrompt ? handleInstall : undefined}
            onViewInstructions={() => setView('instructions')}
          />
        )}

        {view === 'instructions' && (
          <InstructionsView onBack={() => setView('profile')} />
        )}
      </main>

      <Footer setView={setView as any} currentView={view} />
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { UserProfile } from '../types';

interface ProfileSetupProps {
  profile: UserProfile | null;
  onSave: (profile: UserProfile) => void;
  onCancel?: () => void;
  onInstall?: () => void;
  onViewInstructions?: () => void;
}

const ProfileSetup: React.FC<ProfileSetupProps> = ({ profile, onSave, onCancel, onInstall, onViewInstructions }) => {
  const [formData, setFormData] = useState<UserProfile>(profile || {
    name: '',
    weight: 70,
    height: 170,
    age: 25,
    gender: 'male',
    activityLevel: 'moderate',
    dailyGoal: 2000
  });

  const [isIOS, setIsIOS] = useState(false);

  useEffect(() => {
    const userAgent = window.navigator.userAgent.toLowerCase();
    setIsIOS(/iphone|ipad|ipod/.test(userAgent));
  }, []);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: name === 'gender' || name === 'activityLevel' || name === 'name' ? value : Number(value)
    }));
  };

  const calculateSuggestedCalories = () => {
    let bmr = 0;
    if (formData.gender === 'male') {
      bmr = 10 * formData.weight + 6.25 * formData.height - 5 * formData.age + 5;
    } else {
      bmr = 10 * formData.weight + 6.25 * formData.height - 5 * formData.age - 161;
    }
    const multipliers = { sedentary: 1.2, light: 1.375, moderate: 1.55, active: 1.725 };
    const tdee = bmr * multipliers[formData.activityLevel];
    setFormData(prev => ({ ...prev, dailyGoal: Math.round(tdee) }));
  };

  return (
    <div className="p-6 space-y-8 pb-32">
      <div>
        <h2 className="text-3xl font-black text-zinc-100 tracking-tight">Settings</h2>
        <p className="text-zinc-500 text-sm">Fine-tune your NoTripChef engine.</p>
      </div>

      <section className="space-y-4">
        <h4 className="text-[10px] font-black text-zinc-500 uppercase ml-1 tracking-widest">Support & Guide</h4>
        <div className="grid gap-3">
          <button 
            onClick={onViewInstructions}
            className="bg-zinc-900 border border-zinc-800 rounded-2xl p-5 flex items-center gap-4 transition-all hover:border-zinc-700 group active:scale-95"
          >
            <div className="bg-zinc-800 w-12 h-12 rounded-2xl flex items-center justify-center text-zinc-100 group-hover:bg-zinc-700 transition-colors shadow-lg">
              <i className="fas fa-book-open text-lg"></i>
            </div>
            <div className="text-left">
              <h4 className="font-black text-base leading-tight">User Guide</h4>
              <p className="text-[10px] text-zinc-600 uppercase font-black tracking-widest mt-0.5">Learn how to master your pantry</p>
            </div>
            <i className="fas fa-chevron-right ml-auto text-zinc-600"></i>
          </button>
        </div>
      </section>

      <section className="space-y-4">
        <h4 className="text-[10px] font-black text-zinc-500 uppercase ml-1 tracking-widest">Mobile Experience</h4>

        <div className="grid gap-3">
          {onInstall ? (
            <button 
              onClick={onInstall}
              className="bg-zinc-100 rounded-2xl p-5 text-zinc-950 shadow-xl shadow-white/5 flex items-center gap-4 transition-transform active:scale-95 group border-2 border-zinc-100 hover:bg-zinc-200"
            >
              <div className="bg-zinc-950 w-12 h-12 rounded-2xl flex items-center justify-center text-zinc-100 group-hover:bg-zinc-800 transition-colors shadow-lg">
                <i className="fas fa-download text-lg"></i>
              </div>
              <div className="text-left">
                <h4 className="font-black text-base leading-tight">Install NoTripChef</h4>
                <p className="text-[10px] text-zinc-600 uppercase font-black tracking-widest mt-0.5">Download direct to home screen</p>
              </div>
              <i className="fas fa-chevron-right ml-auto text-zinc-400"></i>
            </button>
          ) : isIOS ? (
            <div className="bg-zinc-900/50 border border-zinc-800 rounded-2xl p-5 space-y-3">
              <div className="flex items-center gap-3">
                <div className="bg-zinc-800 w-10 h-10 rounded-xl flex items-center justify-center text-zinc-400">
                  <i className="fas fa-mobile-screen"></i>
                </div>
                <div>
                  <h4 className="font-bold text-sm text-zinc-100">iOS Installation</h4>
                  <p className="text-[9px] text-zinc-500 font-black uppercase tracking-widest">Add to Home Screen</p>
                </div>
              </div>
              <div className="text-[11px] text-zinc-400 leading-relaxed bg-zinc-950 p-3 rounded-xl border border-zinc-800">
                Tap the <i className="fas fa-share-square text-zinc-100 mx-1"></i> Share button in your Safari browser and select <span className="text-zinc-100 font-bold italic">"Add to Home Screen"</span> to download the app.
              </div>
            </div>
          ) : (
            <div className="bg-zinc-900/50 border border-zinc-800 rounded-2xl p-5 text-center">
              <p className="text-xs text-zinc-500 font-medium">App is already installed or your browser handles installation via its menu.</p>
            </div>
          )}
        </div>
      </section>

      <div className="space-y-6">
        <div className="space-y-4">
          <div>
            <label className="block text-[10px] font-black text-zinc-500 uppercase mb-2 ml-1 tracking-widest">Chef Handle</label>
            <input 
              type="text" 
              name="name" 
              value={formData.name} 
              onChange={handleChange}
              placeholder="Your Name"
              className="w-full bg-zinc-900 border border-zinc-800 rounded-2xl px-5 py-4 focus:ring-1 focus:ring-zinc-500 focus:outline-none font-semibold text-zinc-100 placeholder-zinc-700"
            />
          </div>

          <div className="pt-6 border-t border-zinc-800">
            <h4 className="text-[10px] font-black text-zinc-500 uppercase mb-4 ml-1 tracking-widest">Body Metrics</h4>
            <div className="grid grid-cols-2 gap-4 mb-4">
              <div>
                <label className="block text-[10px] font-bold text-zinc-600 uppercase mb-2 ml-1">Weight (kg)</label>
                <input type="number" name="weight" value={formData.weight} onChange={handleChange} className="w-full bg-zinc-900 border border-zinc-800 rounded-2xl px-4 py-3 text-zinc-100" />
              </div>
              <div>
                <label className="block text-[10px] font-bold text-zinc-600 uppercase mb-2 ml-1">Height (cm)</label>
                <input type="number" name="height" value={formData.height} onChange={handleChange} className="w-full bg-zinc-900 border border-zinc-800 rounded-2xl px-4 py-3 text-zinc-100" />
              </div>
            </div>

            <div className="flex justify-between items-center mb-2 px-1">
              <label className="block text-[10px] font-black text-zinc-500 uppercase">Calorie Target</label>
              <button onClick={calculateSuggestedCalories} className="text-zinc-400 text-[10px] font-black uppercase tracking-wider hover:text-zinc-100">Auto-Tune</button>
            </div>
            <input 
              type="number" 
              name="dailyGoal" 
              value={formData.dailyGoal} 
              onChange={handleChange}
              className="w-full bg-zinc-900 border border-zinc-800 rounded-2xl px-5 py-5 text-zinc-100 font-black text-2xl"
            />
          </div>
        </div>

        <div className="flex gap-3 pt-6">
          {onCancel && (
            <button onClick={onCancel} className="flex-1 bg-zinc-900 text-zinc-600 font-bold py-4 rounded-2xl border border-zinc-800">Cancel</button>
          )}
          <button 
            onClick={() => onSave(formData)}
            className="flex-[2] bg-zinc-100 text-zinc-950 font-bold py-4 rounded-2xl shadow-xl shadow-white/5 active:scale-95 transition-all"
          >
            Confirm Changes
          </button>
        </div>
      </div>
    </div>
  );
};

