  const [isLoading, setIsLoading] = useState(false);
  const [deferredPrompt, setDeferredPrompt] = useState<any>(null);

  useEffect(() => {
    const savedMeals = localStorage.getItem('notripchef_meals');
    const savedProfile = localStorage.getItem('notripchef_profile');
    const savedPantry = localStorage.getItem('notripchef_pantry');
    const savedRecs = localStorage.getItem('notripchef_saved_recipes');

    if (savedMeals) setMeals(JSON.parse(savedMeals));
    if (savedPantry) setPantry(JSON.parse(savedPantry));
    if (savedProfile) setProfile(JSON.parse(savedProfile));
    if (savedRecs) setSavedRecipes(JSON.parse(savedRecs));

    window.addEventListener('beforeinstallprompt', (e) => {
      e.preventDefault();
      setDeferredPrompt(e);
    });
  }, []);

  useEffect(() => {
    localStorage.setItem('notripchef_meals', JSON.stringify(meals));
    localStorage.setItem('notripchef_pantry', JSON.stringify(pantry));
    localStorage.setItem('notripchef_saved_recipes', JSON.stringify(savedRecipes));
    if (profile) localStorage.setItem('notripchef_profile', JSON.stringify(profile));
  }, [meals, pantry, profile, savedRecipes]);

  const handleInstall = async () => {
    if (deferredPrompt) {
      deferredPrompt.prompt();
      const { outcome } = await deferredPrompt.userChoice;
      if (outcome === 'accepted') setDeferredPrompt(null);
    }
  };

  const handleAddMeal = (meal: Meal) => {
    setMeals(prev => [meal, ...prev]);
    setView('dashboard');
  };

  return (
    <div className="min-h-screen flex flex-col max-w-md mx-auto bg-zinc-950 shadow-2xl relative overflow-hidden text-zinc-100">
      <Header setView={setView as any} currentView={view} />

      <main className="flex-1 overflow-y-auto pb-24 scroll-smooth">
        {view === 'pantry' && (
          <PantryView 
            items={pantry} 
            setItems={setPantry}
            savedRecipes={savedRecipes}
            setSavedRecipes={setSavedRecipes}
            onViewCookbook={() => setView('cookbook')}
          />
        )}

        {view === 'cookbook' && (
          <CookbookView 
            recipes={savedRecipes}
            setSavedRecipes={setSavedRecipes}
            onBack={() => setView('pantry')}
            viewTitle="Cookbook"
            emptyMessage="Your cookbook is empty. Generate a recipe in the kitchen and save it to see it here."
          />
        )}

        {view === 'dietPlan' && (
          <DietPlanView 
            profile={profile}
            pantry={pantry}
            onBack={() => setView('profile')}
          />
        )}

        {view === 'dashboard' && profile && (
          <Dashboard 
            meals={meals} 
            profile={profile} 
            onDeleteMeal={(id) => setMeals(m => m.filter(x => x.id !== id))}
            onAddClick={() => setView('logger')}
          />
        )}

        {view === 'logger' && (
          <MealLogger 
            onSave={handleAddMeal} 
            onCancel={() => setView('dashboard')}
            isLoading={isLoading}
            setIsLoading={setIsLoading}
          />
        )}

        {view === 'profile' && (
          <ProfileSetup 
            profile={profile} 
            onSave={(p) => { setProfile(p); setView('pantry'); }} 
            onCancel={() => setView('pantry')}
          />
        )}

        {view === 'settings' && (
          <SettingsView 
            onViewInstructions={() => setView('instructions')}
            onInstall={deferredPrompt ? handleInstall : undefined}
          />
        )}

        {view === 'instructions' && (
          <InstructionsView onBack={() => setView('settings')} />
        )}
      </main>

      <Footer setView={setView as any} currentView={view} />
    </div>
  );
};

export default App;

