import React, { useState, useRef } from 'react';
import { GroceryItem, Recipe } from '../types';
import { analyzeGroceries, generateRecipeFromGroceries } from '../services/geminiService';
import BrandLogo from './BrandLogo';

interface PantryViewProps {
  items: GroceryItem[];
  setItems: React.Dispatch<React.SetStateAction<GroceryItem[]>>;
  savedRecipes: Recipe[];
  setSavedRecipes: React.Dispatch<React.SetStateAction<Recipe[]>>;
  onViewCookbook: () => void;
}

const PantryView: React.FC<PantryViewProps> = ({ items, setItems, savedRecipes, setSavedRecipes, onViewCookbook }) => {
  const [isScanning, setIsScanning] = useState(false);
  const [isGenerating, setIsGenerating] = useState(false);
  const [recipe, setRecipe] = useState<Recipe | null>(null);
  const [feedbackText, setFeedbackText] = useState('');
  const [showFeedbackInput, setShowFeedbackInput] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const getCategoryIcon = (category: string) => {
    const cat = category.toLowerCase();
    if (cat.includes('veg')) return 'fa-carrot';
    if (cat.includes('fruit')) return 'fa-apple-whole';
    if (cat.includes('meat') || cat.includes('protein') || cat.includes('chicken') || cat.includes('beef')) return 'fa-drumstick-bite';
    if (cat.includes('fish') || cat.includes('seafood')) return 'fa-fish';
    if (cat.includes('grain') || cat.includes('rice') || cat.includes('wheat')) return 'fa-wheat-awn';
    if (cat.includes('spice') || cat.includes('seasoning') || cat.includes('masala')) return 'fa-pepper-hot';
    if (cat.includes('dairy') || cat.includes('milk') || cat.includes('cheese')) return 'fa-cheese';
    if (cat.includes('oil') || cat.includes('ghee')) return 'fa-bottle-droplet';
    if (cat.includes('pulse') || cat.includes('dal') || cat.includes('lentil')) return 'fa-seedling';
    return 'fa-box-archive';
  };

  const handleScan = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setIsScanning(true);
    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64 = (reader.result as string).split(',')[1];
      try {
        const detected = await analyzeGroceries(base64);
        setItems(prev => [...detected, ...prev]);
      } catch (err) {
        alert("Pantry scan failed. Please check your connection.");
      } finally {
        setIsScanning(false);
      }
    };
    reader.readAsDataURL(file);
  };

  const handleQuantityChange = (id: string, value: string) => {
    setItems(items.map(item => item.id === id ? { ...item, quantity: value } : item));
  };

  const handleGetRecipe = async (feedback?: string) => {
    if (items.length === 0) {
      alert("Scan some items in your fridge first!");
      return;
    }
    setIsGenerating(true);
    if (!feedback) setRecipe(null);
    setShowFeedbackInput(false);
    try {
      const pantryStrings = items.map(i => i.quantity ? `${i.quantity} ${i.name}` : i.name);
      const result = await generateRecipeFromGroceries(pantryStrings, feedback);
      setRecipe({ ...result, id: Date.now().toString() });
      if (feedback) setFeedbackText('');
    } catch (err) {
      alert("Recipe generation failed. Try adding more items.");
    } finally {
      setIsGenerating(false);
    }
  };

  const handleSaveToCookbook = () => {
    if (!recipe) return;
    const isAlreadySaved = savedRecipes.some(r => r.title === recipe.title);
    if (!isAlreadySaved) {
      setSavedRecipes(prev => [recipe, ...prev]);
      alert(`${recipe.title} added to your Cookbook!`);
    } else {
      alert("This recipe is already in your cookbook!");
    }
  };

  const handleRating = (rating: 'up' | 'down') => {
    if (!recipe) return;
    const newRating = recipe.userRating === rating ? null : rating;
    const updatedRecipe = { ...recipe, userRating: newRating };
    setRecipe(updatedRecipe);

    if (newRating === 'down') {
      setShowFeedbackInput(true);
    } else {
      setShowFeedbackInput(false);
    }

    setSavedRecipes(prev => {
      const existingIndex = prev.findIndex(r => r.title === updatedRecipe.title);
      if (existingIndex > -1) {
        const newSaved = [...prev];
        newSaved[existingIndex] = updatedRecipe;
        return newSaved;
      }
      return prev;
    });
  };

  const openOrderLink = (platform: 'chaldal' | 'pathao' | 'pandamart', item: string) => {
    let url = '';
    const query = encodeURIComponent(item);
    switch (platform) {
      case 'chaldal': url = `https://chaldal.com/search/${query}`; break;
      case 'pathao': url = `https://pathao.com/food/`; break;
      case 'pandamart': url = `https://www.foodpanda.com.bd/darkstore/search?q=${query}`; break;
    }
    window.open(url, '_blank');
  };

  const handleShare = async () => {
    if (!recipe) return;
    const shareText = `🍳 ${recipe.title}\n"${recipe.description}"\n\n🛒 Ingredients:\n${recipe.ingredients.map(i => `- ${i}`).join('\n')}\n\n👨‍🍳 Instructions:\n${recipe.instructions.map((step, i) => `${i + 1}. ${step}`).join('\n')}\n\nShared via ElaChef 🥗`.trim();
    if (navigator.share) {
      try { await navigator.share({ title: recipe.title, text: shareText }); } catch (err) { }
    } else {
      try { await navigator.clipboard.writeText(shareText); alert('Recipe copied to clipboard!'); } catch (err) { alert('Could not copy recipe.'); }
    }
  };

  return (
    <div className="p-5 space-y-8 animate-in fade-in duration-500 pb-20">
      <section className="flex justify-between items-end">
        <div>
          <h2 className="text-3xl font-extrabold text-zinc-100 tracking-tight">Your Kitchen</h2>
          <p className="text-zinc-600 text-sm">Master your inventory.</p>
        </div>
        <button 
          onClick={onViewCookbook}
          className="text-[10px] font-black uppercase text-zinc-500 border border-zinc-800 px-4 py-2 rounded-full hover:bg-zinc-900 transition-colors"
        >
          My Cookbook
        </button>
      </section>

      <div className="bg-zinc-900 rounded-[2.5rem] p-7 border border-zinc-800 shadow-xl relative overflow-hidden">
        <div className="flex justify-between items-center mb-6">
          <h3 className="font-bold text-zinc-600 uppercase tracking-widest text-[9px]">Stockpiled Ingredients</h3>
          <span className="bg-zinc-800 text-zinc-400 text-[9px] font-black px-3 py-1.5 rounded-full border border-zinc-700 tracking-widest">{items.length} TOTAL</span>
        </div>

        <div className="flex flex-col gap-3 min-h-[120px]">
          {items.length === 0 ? (
            <div className="w-full flex flex-col items-center justify-center py-12 text-zinc-700 text-center">
              <div className="w-20 h-20 bg-zinc-950 rounded-3xl flex items-center justify-center mb-6 border border-zinc-800/50">
                <BrandLogo size="md" className="opacity-10 text-white" />
              </div>
              <p className="text-sm font-bold text-zinc-400">Inventory is empty</p>
              <p className="text-[10px] uppercase font-black tracking-widest opacity-40 mt-1">Add items to unlock recipes</p>
            </div>
          ) : (
            <div className="space-y-2 max-h-[350px] overflow-y-auto pr-1">
              {items.map(item => (
                <div key={item.id} className="bg-zinc-950 border border-zinc-800 px-4 py-4 rounded-2xl shadow-sm flex items-center justify-between group hover:border-zinc-700 transition-colors">
                  <div className="flex items-center gap-3 flex-1 min-w-0">
                    <div className="bg-zinc-900 w-9 h-9 rounded-xl flex items-center justify-center text-zinc-500 flex-shrink-0 border border-zinc-800">
                      <i className={`fas ${getCategoryIcon(item.category)} text-sm text-zinc-300`}></i>
                    </div>
                    <div className="flex flex-col min-w-0">
                      <span className="text-sm font-bold text-zinc-300 truncate">{item.name}</span>
                      <span className="text-[9px] text-zinc-600 font-black uppercase tracking-tighter">{item.category}</span>
                    </div>
                  </div>

                  <div className="flex items-center gap-2">
                    <input 
                      type="text"
                      placeholder="Amt"
                      value={item.quantity || ''}
                      onChange={(e) => handleQuantityChange(item.id, e.target.value)}
                      className="bg-zinc-900 border border-zinc-800 text-[10px] font-bold px-2 py-2 rounded-xl focus:ring-1 focus:ring-zinc-600 outline-none w-16 text-zinc-400 placeholder:text-zinc-800 text-center transition-all focus:w-20"
                    />
                    <button onClick={() => setItems(prev => prev.filter(i => i.id !== item.id))} className="w-8 h-8 flex items-center justify-center text-zinc-800 hover:text-rose-900 transition-colors">
                      <i className="fas fa-trash-can text-xs"></i>
                    </button>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>

        <button 
          onClick={() => fileInputRef.current?.click()}
          className="mt-8 w-full bg-zinc-100 text-zinc-950 py-5 rounded-3xl font-black text-sm flex items-center justify-center gap-3 active:scale-95 transition-all shadow-2xl shadow-white/5"
        >
          <i className={`fas ${isScanning ? 'fa-spinner fa-spin' : 'fa-camera'}`}></i>
          {isScanning ? 'Syncing Pantry...' : 'Add Ingredients'}
        </button>
        <input type="file" className="hidden" ref={fileInputRef} onChange={handleScan} accept="image/*" />
      </div>

      <button 
        onClick={() => handleGetRecipe()}
        disabled={isGenerating || items.length === 0}
        className="w-full bg-zinc-900 border border-zinc-800 text-zinc-100 font-black py-6 rounded-[2rem] shadow-xl flex items-center justify-center gap-4 active:scale-95 transition-all disabled:opacity-20 group"
      >
        {isGenerating ? (
          <><i className="fas fa-sparkles fa-spin text-zinc-500"></i> Thinking...</>
        ) : (
          <>
            <i className="fas fa-utensils text-green-500 group-hover:scale-110 transition-transform"></i> 
            Generate Zero-Trip Recipe
          </>
        )}
      </button>

      {recipe && (
        <div className="bg-zinc-900 rounded-[2.5rem] border border-zinc-800 shadow-2xl p-7 space-y-6 animate-in slide-in-from-bottom-10 duration-700">
          <div className="flex justify-between items-start">
            <div className="flex-1 pr-4">
              <div className="flex items-center gap-2 mb-2">
                <span className={`text-[9px] font-black px-2 py-1 rounded-lg uppercase tracking-widest border ${recipe.missingIngredients.length === 0 ? 'bg-emerald-950/30 text-emerald-400 border-emerald-900/50' : 'bg-amber-950/30 text-amber-400 border-amber-900/50'}`}>
                  {recipe.missingIngredients.length === 0 ? 'READY TO COOK' : 'SUBSTITUTES NEEDED'}
                </span>
                <span className="text-zinc-600 font-black text-[10px] uppercase">{recipe.prepTime}</span>
              </div>
              <h3 className="text-2xl font-black text-zinc-100 leading-tight tracking-tight">{recipe.title}</h3>
            </div>
            <div className="flex items-center gap-2">
              <button onClick={handleShare} className="bg-zinc-800 text-zinc-500 w-10 h-10 rounded-full flex items-center justify-center border border-zinc-700 hover:text-zinc-100 transition-all"><i className="fas fa-share-nodes text-sm"></i></button>
              <button onClick={() => setRecipe(null)} className="bg-zinc-800 text-zinc-500 w-10 h-10 rounded-full flex items-center justify-center border border-zinc-700 hover:text-rose-500 transition-all"><i className="fas fa-times"></i></button>
            </div>
          </div>

          <p className="text-zinc-500 text-sm italic leading-relaxed border-l-2 border-zinc-800 pl-4">"{recipe.description}"</p>

          <button 
            onClick={handleSaveToCookbook}
            className={`w-full py-5 rounded-[1.5rem] font-black text-[10px] uppercase tracking-widest flex items-center justify-center gap-2 transition-all ${
              savedRecipes.some(r => r.title === recipe.title) 
                ? 'bg-emerald-600 text-white shadow-lg' 
                : 'bg-zinc-800 text-zinc-100 border border-zinc-700 hover:bg-zinc-700'
            }`}
          >
            <i className={`fas ${savedRecipes.some(r => r.title === recipe.title) ? 'fa-check-double' : 'fa-bookmark'}`}></i>
            {savedRecipes.some(r => r.title === recipe.title) ? 'Added to Cookbook' : 'Save to Cookbook'}
          </button>

          {recipe.missingIngredients.length > 0 && (
            <div className="bg-amber-950/10 rounded-[2rem] p-6 border border-amber-900/20 space-y-4">
              <h4 className="text-[10px] font-black text-amber-600 uppercase tracking-widest flex items-center gap-2">
                <i className="fas fa-sparkles"></i> AI Substitute Assistant
              </h4>
              <div className="flex flex-col gap-3">
                {recipe.missingIngredients.map((missing, i) => (
                  <div key={i} className="bg-zinc-950 p-4 rounded-2xl border border-amber-900/10 shadow-sm space-y-2">
                    <div className="text-xs font-black text-zinc-100 uppercase">{missing.name}</div>
                    {missing.alternative && (
                      <p className="text-[11px] text-zinc-500 leading-tight">
                        <span className="text-amber-600 font-bold uppercase text-[9px]">Swap for:</span> {missing.alternative}
                      </p>
                    )}
                    <div className="flex flex-wrap gap-2 pt-2">
                      <button onClick={() => openOrderLink('chaldal', missing.name)} className="text-[9px] font-black bg-[#ffeb3b] text-slate-900 px-3 py-1.5 rounded-lg border border-yellow-400 uppercase">Chaldal</button>
                      <button onClick={() => openOrderLink('pandamart', missing.name)} className="text-[9px] font-black bg-[#D70F64] text-white px-3 py-1.5 rounded-lg uppercase">PandaMart</button>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}

          <div className="space-y-4">
            <h4 className="font-black text-zinc-100 text-[10px] uppercase tracking-[0.2em] border-b border-zinc-800 pb-3">Cooking Instructions</h4>
            <div className="space-y-6">
              {recipe.instructions.map((step, i) => (
                <div key={i} className="flex gap-4 items-start">
                  <div className="bg-zinc-100 text-zinc-950 w-7 h-7 rounded-xl flex items-center justify-center text-xs font-black flex-shrink-0 mt-0.5 shadow-lg shadow-white/5">{i+1}</div>
                  <p className="text-sm text-zinc-400 leading-relaxed font-medium">{step}</p>
                </div>
              ))}
            </div>
          </div>

          {recipe.bangladeshiContext && (
            <div className="p-5 bg-zinc-950 rounded-2xl border border-zinc-800">
               <span className="text-[9px] font-black text-zinc-600 uppercase tracking-widest block mb-2">Regional Context</span>
               <p className="text-[11px] text-zinc-500 italic leading-snug">{recipe.bangladeshiContext}</p>
            </div>
          )}

          <div className="pt-6 border-t border-zinc-800 flex flex-col items-center gap-5">
            <p className="text-[10px] font-black text-zinc-600 uppercase tracking-widest">How was this recipe?</p>
            <div className="flex gap-6">
              <button 
                onClick={() => handleRating('up')} 
                className={`w-16 h-16 rounded-[1.5rem] flex items-center justify-center transition-all ${recipe.userRating === 'up' ? 'bg-zinc-100 text-zinc-950 shadow-2xl scale-110' : 'bg-zinc-900 text-zinc-600 border border-zinc-800'}`}
              >
                <i className="fas fa-thumbs-up text-xl"></i>
              </button>
              <button 
                onClick={() => handleRating('down')} 
                className={`w-16 h-16 rounded-[1.5rem] flex items-center justify-center transition-all ${recipe.userRating === 'down' ? 'bg-rose-950 text-rose-500 border border-rose-900 shadow-2xl scale-110' : 'bg-zinc-900 text-zinc-600 border border-zinc-800'}`}
              >
                <i className="fas fa-thumbs-down text-xl"></i>
              </button>
            </div>

            {showFeedbackInput && (
              <div className="w-full space-y-4 animate-in fade-in slide-in-from-top-4 duration-500">
                <textarea
                  value={feedbackText}
                  onChange={(e) => setFeedbackText(e.target.value)}
                  placeholder="Tell Chef Gemini what to change... (e.g., I don't like mustard oil, or make it spicier)"
                  className="w-full bg-zinc-950 border border-zinc-800 rounded-2xl p-4 text-xs text-zinc-300 placeholder:text-zinc-800 focus:ring-1 focus:ring-zinc-600 outline-none min-h-[100px] resize-none"
                />
                <button 
                  onClick={() => handleGetRecipe(feedbackText)}
                  disabled={isGenerating || !feedbackText.trim()}
                  className="w-full bg-zinc-100 text-zinc-950 font-black py-5 rounded-[1.5rem] text-[10px] uppercase tracking-widest hover:bg-white disabled:opacity-20 transition-all flex items-center justify-center gap-3"
                >
                  <i className="fas fa-rotate"></i>
                  Regenerate with Feedback
                </button>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

export default PantryView;

import React, { useState, useEffect } from 'react';
import { Recipe } from '../types';

interface CookbookViewProps {
  recipes: Recipe[];
  setSavedRecipes: React.Dispatch<React.SetStateAction<Recipe[]>>;
  onBack: () => void;
  viewTitle?: string;
  emptyMessage?: string;
  sharedRecipe?: Recipe | null;
  onClearShared?: () => void;
}

const CookbookView: React.FC<CookbookViewProps> = ({ 
  recipes, 
  setSavedRecipes, 
  onBack, 
  viewTitle = "Cookbook",
  emptyMessage = "Your cookbook is empty. Generate a recipe in the kitchen and save it to see it here.",
  sharedRecipe,
  onClearShared
}) => {
  const [selectedRecipe, setSelectedRecipe] = useState<Recipe | null>(null);
  const [showToast, setShowToast] = useState(false);

  useEffect(() => {
    if (sharedRecipe) {
      setSelectedRecipe(sharedRecipe);
    }
  }, [sharedRecipe]);

  const handleDelete = (id: string | undefined) => {
    if (!id) return;
    if (confirm("Remove this recipe from your collection?")) {
      setSavedRecipes(prev => prev.filter(r => r.id !== id));
      if (selectedRecipe?.id === id) setSelectedRecipe(null);
    }
  };

  const handleShare = async (recipe: Recipe) => {
    // Generate a deep link by encoding the recipe data
    const recipeData = btoa(JSON.stringify(recipe));
    const shareUrl = `${window.location.origin}${window.location.pathname}?share=${recipeData}`;

    const shareText = `🍳 ${recipe.title}\n"${recipe.description}"\n\nTry this recipe on ElaChef: ${shareUrl}`.trim();

    if (navigator.share) {
      try { 
        await navigator.share({ 
          title: `ElaChef: ${recipe.title}`, 
          text: shareText,
          url: shareUrl
        }); 
      } catch (err) { }
    } else {
      try { 
        await navigator.clipboard.writeText(shareUrl); 
        setShowToast(true);
        setTimeout(() => setShowToast(false), 3000);
      } catch (err) { 
        alert('Could not copy link.'); 
      }
    }
  };

  const handleSaveShared = () => {
    if (selectedRecipe) {
      setSavedRecipes(prev => {
        if (prev.some(r => r.title === selectedRecipe.title)) return prev;
        return [selectedRecipe, ...prev];
      });
      alert("Recipe saved to your cookbook!");
    }
  };

  return (
    <div className="p-5 space-y-8 animate-in fade-in duration-500 pb-20 relative">
      <header className="flex items-center gap-4">
        <button onClick={onBack} className="text-zinc-600 hover:text-zinc-300">
          <i className="fas fa-chevron-left"></i>
        </button>
        <div>
          <h2 className="text-3xl font-extrabold text-zinc-100 tracking-tight">{viewTitle}</h2>
          <p className="text-zinc-500 text-sm">Your private collection of verified tastes.</p>
        </div>
      </header>

      {recipes.length === 0 && !sharedRecipe ? (
        <div className="flex flex-col items-center justify-center py-20 text-center space-y-4">
          <div className="w-20 h-20 bg-zinc-900 rounded-full flex items-center justify-center text-zinc-800 border border-zinc-800">
            <i className={`fas ${viewTitle.toLowerCase().includes('like') ? 'fa-heart' : 'fa-book-open'} text-3xl opacity-20`}></i>
          </div>
          <div>
            <p className="text-zinc-400 font-bold">Collection is empty</p>
            <p className="text-xs text-zinc-600 max-w-[200px] mt-1">{emptyMessage}</p>
          </div>
          <button 
            onClick={onBack}
            className="text-[10px] font-black uppercase tracking-widest bg-zinc-100 text-zinc-950 px-6 py-3 rounded-full shadow-lg"
          >
            Back to Kitchen
          </button>
        </div>
      ) : (
        <div className="grid grid-cols-1 gap-4">
          {recipes.map(recipe => (
            <div 
              key={recipe.id} 
              className="bg-zinc-900 border border-zinc-800 rounded-[2rem] p-5 shadow-sm hover:border-zinc-700 transition-all group"
            >
              <div className="flex justify-between items-start mb-4">
                <div className="flex-1 cursor-pointer" onClick={() => setSelectedRecipe(recipe)}>
                  <div className="flex items-center gap-2 mb-1">
                    <span className="text-[9px] font-black uppercase text-zinc-500 tracking-wider">{recipe.prepTime}</span>
                    {recipe.userRating === 'up' && <i className="fas fa-heart text-rose-500 text-[10px]"></i>}
                  </div>
                  <h3 className="text-xl font-black text-zinc-100 leading-tight group-hover:text-white">{recipe.title}</h3>
                </div>
                <div className="flex gap-2">
                  <button onClick={() => handleShare(recipe)} className="w-8 h-8 rounded-full flex items-center justify-center text-zinc-600 hover:text-green-500 hover:bg-zinc-800" title="Get Share Link"><i className="fas fa-link text-xs"></i></button>
                  <button onClick={() => handleDelete(recipe.id)} className="w-8 h-8 rounded-full flex items-center justify-center text-zinc-600 hover:text-rose-500 hover:bg-zinc-800"><i className="fas fa-trash-can text-xs"></i></button>
                </div>
              </div>

              <p className="text-zinc-500 text-xs line-clamp-2 italic mb-4">"{recipe.description}"</p>

              <button 
                onClick={() => setSelectedRecipe(recipe)}
                className="w-full bg-zinc-950 border border-zinc-800 text-zinc-400 font-black text-[10px] uppercase py-3 rounded-xl hover:text-zinc-100 transition-colors"
              >
                View Full Recipe
              </button>
            </div>
          ))}
        </div>
      )}

      {selectedRecipe && (
        <div className="fixed inset-0 z-[100] bg-zinc-950 overflow-y-auto p-5 animate-in slide-in-from-bottom-20 duration-500">
          <div className="max-w-md mx-auto space-y-6 pb-20">
            <header className="flex justify-between items-start">
              <button onClick={() => { setSelectedRecipe(null); if(onClearShared) onClearShared(); }} className="w-10 h-10 bg-zinc-900 rounded-full flex items-center justify-center text-zinc-400"><i className="fas fa-times"></i></button>
              <div className="flex gap-2">
                <button onClick={() => handleShare(selectedRecipe)} className="w-10 h-10 bg-zinc-900 rounded-full flex items-center justify-center text-zinc-400"><i className="fas fa-link"></i></button>
              </div>
            </header>

            <div className="space-y-4">
              {sharedRecipe && (
                <div className="bg-green-500/10 border border-green-500/20 rounded-2xl p-4 flex items-center justify-between mb-2">
                  <p className="text-[10px] font-black text-green-500 uppercase">Received Shared Recipe</p>
                  <button onClick={handleSaveShared} className="bg-green-500 text-black text-[9px] font-black px-3 py-1.5 rounded-lg uppercase">Save to My Library</button>
                </div>
              )}
              <div className="flex items-center gap-2">
                <span className="bg-emerald-950/30 text-emerald-400 text-[10px] font-black px-2 py-0.5 rounded-full uppercase border border-emerald-900/50">{selectedRecipe.prepTime}</span>
                <span className="text-zinc-500 text-[10px] uppercase font-bold tracking-widest">{selectedRecipe.servings} Servings</span>
              </div>
              <h2 className="text-4xl font-black text-zinc-100 leading-none">{selectedRecipe.title}</h2>
              <p className="text-zinc-500 italic">"{selectedRecipe.description}"</p>
            </div>

            <div className="space-y-4 bg-zinc-900/50 p-6 rounded-[2.5rem] border border-zinc-900">
              <h4 className="text-xs font-black text-zinc-100 uppercase tracking-widest border-b border-zinc-800 pb-2">Ingredients</h4>
              <ul className="space-y-2">
                {selectedRecipe.ingredients.map((ing, i) => (
                  <li key={i} className="text-sm text-zinc-400 flex items-center gap-3">
                    <div className="w-1.5 h-1.5 rounded-full bg-green-500"></div>
                    {ing}
                  </li>
                ))}
              </ul>
            </div>

            <div className="space-y-4">
              <h4 className="text-xs font-black text-zinc-100 uppercase tracking-widest border-b border-zinc-800 pb-2">Instructions</h4>
              <div className="space-y-6">
                {selectedRecipe.instructions.map((step, i) => (
                  <div key={i} className="flex gap-4 items-start">
                    <div className="bg-green-500 text-black w-6 h-6 rounded-lg flex items-center justify-center text-[10px] font-bold flex-shrink-0 mt-0.5">{i+1}</div>
                    <p className="text-sm text-zinc-400 leading-relaxed">{step}</p>
                  </div>
                ))}
              </div>
            </div>

            <div className="pt-10">
              <button 
                onClick={() => { setSelectedRecipe(null); if(onClearShared) onClearShared(); }}
                className="w-full bg-zinc-100 text-zinc-950 font-black py-5 rounded-[2rem] shadow-xl"
              >
                Close Recipe
              </button>
            </div>
          </div>
        </div>
      )}

      {showToast && (
        <div className="fixed bottom-24 left-1/2 -translate-x-1/2 bg-green-500 text-black px-6 py-3 rounded-full font-black text-[10px] uppercase shadow-2xl z-[200] animate-in fade-in slide-in-from-bottom-5">
          Link Copied to Clipboard!
        </div>
      )}
    </div>
  );
};

export default CookbookView;

